    class TestStreamDecoder(unittest.TestCase):
        def test_every_single_byte_split_matches_the_unsplit_stream(self) -> None:
            samples = {
                "sse": 'data: {"choices":[{"delta":{"content":"\u0633\u0644\u0627\u0645 \U0001F642"}}]}\r\n\r\ndata: [DONE]\n\n',
                "ndjson": '{"text":"\u0633\u0644\u0627\u0645 \U0001F642"}\r\n{"text":"next"}',
                "json": '{"text":"\u0633\u0644\u0627\u0645 \U0001F642","items":[1,2]}',
                "text": "print('\u0633\u0644\u0627\u0645 \U0001F642')\r\n",
            }
            for fmt, sample in samples.items():
                wire = sample.encode("utf-8")
                expected = parse_events(fmt, sample)
                for cut in range(len(wire) + 1):
                    decoder = StreamDecoder(fmt)
                    got = decoder.feed(wire[:cut]) + decoder.feed(wire[cut:]) + decoder.close()
                    if fmt == "text":
                        self.assertEqual("".join(got), sample, (fmt, cut))
                    else:
                        self.assertEqual(got, expected, (fmt, cut))

        def test_one_byte_reads_preserve_utf8_and_flush_the_final_line(self) -> None:
            for fmt, text in (("text", "\u067e\u0627\u0633\u062e\U0001F642"), ("sse", 'data: {"text":"\u067e\u0627\u0633\u062e\U0001F642"}')):
                wire = text.encode("utf-8")
                decoder = StreamDecoder(fmt)
                events: List[Any] = []
                for byte in wire:
                    events.extend(decoder.feed(bytes([byte])))
                events.extend(decoder.close())
                if fmt == "text":
                    self.assertEqual("".join(events), text)
                else:
                    self.assertEqual(events, [{"text": "\u067e\u0627\u0633\u062e\U0001F642"}])

    class TestRouterCore(unittest.TestCase):
        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env({"cache_seconds": 60})
            self.a = add_acct(self.app, "a1", "Alpha", "alpha.test")
            self.b = add_acct(self.app, "b2", "Beta", "beta.test")
            self.calls: List[str] = []
            self.lock = threading.Lock()
            self.live: Dict[str, int] = {}
            self.peak: Dict[str, int] = {}

            def fake_run(acct: Dict[str, Any], req: NormReq, emit: Callable[[str], None], cancel: threading.Event) -> Outcome:
                with self.lock:
                    self.calls.append(acct["id"])
                    self.live[acct["id"]] = self.live.get(acct["id"], 0) + 1
                    self.peak[acct["id"]] = max(self.peak.get(acct["id"], 0), self.live[acct["id"]])
                time.sleep(0.002)
                emit("hi")
                with self.lock:
                    self.live[acct["id"]] -= 1
                return Outcome("hi", [], "hi")
            self.app.router._run = fake_run                                  # type: ignore[assignment]

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def req(self, text: str = "hello", tools: bool = False, model: str = "bridge-auto") -> NormReq:
            d: Dict[str, Any] = {"model": model, "max_tokens": 100, "messages": [{"role": "user", "content": text}]}
            if tools:
                d["tools"] = [{"name": "Bash", "description": "d", "input_schema": {}}]
            return normalize_anthropic(d)

        def run_req(self, r: NormReq, scope: str = "k1", pinned: str = "") -> Outcome:
            return self.app.router.handle(r, lambda t: None, pinned, threading.Event(), scope=scope)

        def test_cache_is_scoped_and_skips_tool_turns(self) -> None:
            self.run_req(self.req())
            self.run_req(self.req())
            self.assertEqual(len(self.calls), 1)                              # same key + same request: cached
            self.run_req(self.req(), scope="k2")
            self.assertEqual(len(self.calls), 2)                              # another key never sees it
            self.run_req(self.req(model="acct:a1"))
            self.assertEqual(len(self.calls), 3)                              # another route never sees it
            self.run_req(self.req(tools=True))
            self.run_req(self.req(tools=True))
            self.assertEqual(len(self.calls), 5)                              # tool turns are never cached

        def test_concurrency_counters_and_limits(self) -> None:
            self.cfg.data["cache_seconds"] = 0
            errs: List[BaseException] = []

            def worker(i: int) -> None:
                try:
                    self.run_req(self.req(f"m{i}"))
                except BaseException as e:                                    # noqa: BLE001
                    errs.append(e)
            ts = [threading.Thread(target=worker, args=(i,)) for i in range(200)]
            for t in ts:
                t.start()
            for t in ts:
                t.join(60)
            self.assertEqual(errs, [])
            self.assertEqual(self.app.router.stats["requests"], 200)
            self.assertEqual(sum(a["requests"] for a in self.app.acc.items), 200)
            self.assertEqual({k: v for k, v in self.app.acc.inflight.items() if v}, {})
            self.assertLessEqual(max(self.peak.values()), 4)                  # direct tier limit
            self.assertEqual(len(set(self.calls)), 2)                         # load was spread

        def test_limiter_follows_tier(self) -> None:
            self.cfg.data["cache_seconds"] = 0
            self.a["tier"] = "ui"                                             # limit 1
            self.b["state"] = "login_required"
            ts = [threading.Thread(target=lambda i=i: self.run_req(self.req(f"u{i}"))) for i in range(12)]
            for t in ts:
                t.start()
            for t in ts:
                t.join(30)
            self.assertEqual(self.peak["a1"], 1)

        def test_queue_wait_is_bounded(self) -> None:
            self.cfg.data["queue_wait_seconds"] = 0.05
            self.b["state"] = "login_required"
            lim = self.app.acc.sem(self.a)
            for _ in range(4):
                self.assertTrue(lim.acquire(0.1))
            with self.assertRaises(BridgeError) as cm:
                self.run_req(self.req("busy"))
            self.assertEqual(cm.exception.kind, "overloaded")

        def test_network_blip_does_not_relearn_or_downgrade_at_once(self) -> None:
            fired: List[str] = []
            self.app.acc.auto_relearn = lambda a, why: fired.append(why)     # type: ignore[assignment]
            e = BridgeError("dns", "network", 502)
            self.assertFalse(self.app.acc.on_error(self.a, e))
            self.assertEqual(self.a["tier"], "direct")                        # one blip: no downgrade
            for _ in range(5):
                self.app.acc.on_error(self.b, BridgeError("boom", "upstream", 502))
            self.assertEqual(fired, [])                                       # outages never trigger relearn

    class TestHTTP(unittest.TestCase):
        def setUp(self) -> None:
            self.tmp, self.store, self.cfg, self.app = mk_env({"cache_seconds": 0})
            self.a = add_acct(self.app, "a1", "Alpha", "alpha.test")
            self.b = add_acct(self.app, "b2", "Beta", "beta.test")
            self.pinned = self.cfg.add_key("pinned", "a1")
            self.key = self.cfg.data["keys"][0]["key"]
            self.admin = self.cfg["admin_key"]
            self.seen: List[Tuple[str, str]] = []

            def fake_run(acct: Dict[str, Any], req: NormReq, emit: Callable[[str], None], cancel: threading.Event) -> Outcome:
                self.seen.append((acct["id"], req.model))
                if getattr(self, "boom", None):
                    emit("partial ")
                    raise BridgeError("upstream exploded", "upstream", 502)
                emit("Hello ")
                emit("world")
                calls = [{"id": "toolu_1", "name": "Bash", "input": {"command": "ls"}}, {"id": "toolu_2", "name": "Bash", "input": {"command": "pwd"}}] if req.tools else []
                return Outcome("Hello world", calls, "Hello world")
            self.app.router._run = fake_run                                  # type: ignore[assignment]
            self.srv = Server(self.app)
            self.p = self.srv.port

        def tearDown(self) -> None:
            self.srv.close()
            shutil.rmtree(self.tmp, ignore_errors=True)

        def msg(self, **kw: Any) -> Dict[str, Any]:
            d = {"model": "claude-sonnet-x", "max_tokens": 100, "messages": [{"role": "user", "content": "hi"}]}
            d.update(kw)
            return d

        def H(self, k: Optional[str] = None) -> Dict[str, str]:
            return {"x-api-key": k or self.key}

        def test_auth_and_models(self) -> None:
            self.assertEqual(call(self.p, "GET", "/v1/models")[0], 401)
            st, _, b = call(self.p, "GET", "/v1/models", headers=self.H())
            ids = [m["id"] for m in json.loads(b)["data"]]
            self.assertEqual(ids[:3], ["bridge-auto", "acct:a1", "acct:b2"])
            self.assertTrue({"opus", "sonnet", "haiku", "claude-sonnet-4-5"} <= set(ids))       # 7.93: Claude-style aliases, all mapped to the bridge routes
            st, _, b = call(self.p, "GET", "/v1/models", headers=self.H(self.pinned["key"]))
            pids = [m["id"] for m in json.loads(b)["data"]]
            self.assertEqual(pids[:2], ["bridge-auto", "acct:a1"])
            self.assertNotIn("acct:b2", pids)                                                 # never lists what the key cannot use
            self.assertEqual(call(self.p, "GET", "/api/state")[0], 401)
            self.assertEqual(call(self.p, "GET", "/api/state", headers={"x-admin-key": self.admin})[0], 200)
            self.assertEqual(call(self.p, "GET", "/api/state", headers={"x-admin-key": self.key})[0], 401)  # a client key is not an admin key

        def test_browser_origin_host_body_limits(self) -> None:
            adm = {"x-admin-key": self.admin}
            self.assertEqual(call(self.p, "GET", "/api/state", headers=dict(adm, Origin="http://evil.example"))[0], 403)
            self.assertEqual(call(self.p, "GET", "/api/state", headers=dict(adm, **{"Sec-Fetch-Site": "cross-site"}))[0], 403)
            self.assertEqual(call(self.p, "GET", "/api/state", headers=dict(adm, Origin=f"http://127.0.0.1:{self.p}"))[0], 200)
            self.assertEqual(call(self.p, "GET", "/health", headers={"Host": "evil.example"})[0], 403)      # DNS-rebinding guard
            self.cfg.data["max_body_mb"] = 1
            st, _, _ = call(self.p, "POST", "/v1/messages", {"x": 1}, dict(self.H(), **{"content-length": "5000000"}))
            self.assertEqual(st, 413)
            st, hdr, _ = call(self.p, "GET", "/")
            self.assertEqual(st, 200)
            self.assertIn("default-src 'none'", hdr["content-security-policy"])
            self.assertEqual(hdr["x-frame-options"], "DENY")

        def test_dashboard_has_no_js_context_interpolation(self) -> None:
            for bad in ("'${a.id}'", "'${k.key}'", "'${k.id}'", "'${esc(r.host)}'"):
                self.assertNotIn(bad, DASHBOARD_HTML)
            self.assertIn("escJ(r.host)", DASHBOARD_HTML)
            self.assertIn("&#39;", DASHBOARD_HTML)

        def test_errors_and_fixed_routes(self) -> None:
            st, _, b = call(self.p, "POST", "/v1/messages", self.msg(model="nonsense"), self.H())
            self.assertEqual(st, 404)
            self.assertEqual(json.loads(b)["error"]["type"], "not_found_error")
            st, _, b = call(self.p, "POST", "/v1/chat/completions", {"model": "nonsense", "messages": [{"role": "user", "content": "x"}]}, self.H())
            self.assertEqual((st, json.loads(b)["error"]["code"]), (404, "model_not_found"))
            st, _, _ = call(self.p, "POST", "/v1/messages", self.msg(model="acct:b2"), self.H(self.pinned["key"]))
            self.assertEqual(st, 404)                                          # key restricted to a1
            self.boom = True
            self.seen.clear()
            st, _, b = call(self.p, "POST", "/v1/messages", self.msg(model="acct:a1"), self.H())
            self.assertEqual(st, 502)
            self.assertEqual({a for a, _ in self.seen}, {"a1"})                # failure did not move to b2

        def test_probe_shortcut_is_strict(self) -> None:
            st, hdr, b = call(self.p, "POST", "/v1/messages", self.msg(max_tokens=1, messages=[{"role": "user", "content": "quota"}]), self.H())
            self.assertEqual((st, hdr.get("x-bridge-shortcut")), (200, "quota-probe"))
            self.assertEqual(self.seen, [])
            st, hdr, b = call(self.p, "POST", "/v1/messages", self.msg(max_tokens=1, messages=[{"role": "user", "content": "real question"}]), self.H())
            self.assertEqual(st, 200)
            self.assertIsNone(hdr.get("x-bridge-shortcut"))
            self.assertEqual(len(self.seen), 1)                                # a real request with max_tokens=1 is NOT swallowed

        def test_headers_and_estimates(self) -> None:
            st, hdr, b = call(self.p, "POST", "/v1/messages", self.msg(temperature=0.2), self.H())
            self.assertEqual(st, 200)
            self.assertEqual(hdr["x-bridge-usage"], "estimated")
            self.assertTrue(hdr["x-bridge-request-id"].startswith("req_"))
            self.assertIn(hdr["x-bridge-account"], ("a1", "b2"))
            self.assertEqual(hdr["x-bridge-ignored-params"], "temperature")
            st, hdr, _ = call(self.p, "POST", "/v1/messages/count_tokens", self.msg(), self.H())
            self.assertEqual(hdr["x-bridge-usage"], "estimated")

        def test_anthropic_stream_conformance(self) -> None:
            tools = [{"name": "Bash", "description": "d", "input_schema": {}}]
            st, hdr, b = call(self.p, "POST", "/v1/messages", self.msg(stream=True), self.H())
            r = check_anthropic(sse_events(b))
            self.assertEqual((r["text"], r["tools"], r["stop_reason"]), ("Hello world", [], "end_turn"))
            self.assertIn("x-bridge-account", hdr)
            st, _, b = call(self.p, "POST", "/v1/messages", self.msg(stream=True, tools=tools), self.H())
            r = check_anthropic(sse_events(b))
            self.assertEqual([t["input"] for t in r["tools"]], [{"command": "ls"}, {"command": "pwd"}])
            self.assertEqual(r["stop_reason"], "tool_use")
            st, _, b = call(self.p, "POST", "/v1/messages", self.msg(tools=tools), self.H())
            j = json.loads(b)
            self.assertEqual([c["type"] for c in j["content"]], ["text", "tool_use", "tool_use"])
            self.assertEqual(j["stop_reason"], "tool_use")

        def test_openai_stream_conformance(self) -> None:
            tools = [{"type": "function", "function": {"name": "Bash", "description": "d", "parameters": {}}}]
            body = {"model": "bridge-auto", "stream": True, "messages": [{"role": "user", "content": "hi"}]}
            st, _, b = call(self.p, "POST", "/v1/chat/completions", body, self.H())
            r = check_openai(b)
            self.assertEqual((r["text"], r["finish"]), ("Hello world", "stop"))
            st, _, b = call(self.p, "POST", "/v1/chat/completions", dict(body, tools=tools), self.H())
            r = check_openai(b)
            self.assertEqual([t["args"] for t in r["tools"]], [{"command": "ls"}, {"command": "pwd"}])
            self.assertEqual(r["finish"], "tool_calls")

        def test_midstream_failure_is_honest(self) -> None:
            self.boom = True
            st, _, b = call(self.p, "POST", "/v1/messages", self.msg(stream=True), self.H())
            evs = sse_events(b)
            r = check_anthropic(evs, expect_error=True)                      # ends with an error event ...
            self.assertEqual(evs[-1][0], "error")
            self.assertNotIn("message_stop", [e[0] for e in evs])            # ... and is never reported as success
            self.assertEqual(r["text"], "partial ")
            self.assertEqual([a for a, _ in self.seen].count("b2") + [a for a, _ in self.seen].count("a1"), len(self.seen))
            self.assertEqual(len(self.seen), 1)                              # no second route was spliced in after output
            self.seen.clear()
            st, _, b = call(self.p, "POST", "/v1/chat/completions", {"model": "bridge-auto", "stream": True, "messages": [{"role": "user", "content": "x"}]}, self.H())
            self.assertIn("error", check_openai(b, expect_error=True))

    class TestPersistence(unittest.TestCase):
        def setUp(self) -> None:
            self.tmp = Path(tempfile.mkdtemp(prefix="bridge_selftest_"))
            self.store = Store(self.tmp)

        def tearDown(self) -> None:
            shutil.rmtree(self.tmp, ignore_errors=True)

        def test_corrupt_critical_file_is_never_overwritten(self) -> None:
            (self.tmp / "config.json").write_text("{ this is not json", "utf-8")
            with self.assertRaises(BridgeError) as cm:
                Config(self.store)
            self.assertIn("damaged", str(cm.exception))
            self.assertEqual((self.tmp / "config.json").read_text("utf-8"), "{ this is not json")
