        def test_migration_from_7_0_layout(self) -> None:
            legacy = [{"id": "L1", "label": "Local", "host": "127.0.0.1", "url": "http://127.0.0.1:1/v1", "type": "api", "api_kind": "openai",
                       "api_base": "http://127.0.0.1:1/v1", "api_model": "m", "state": "ready", "tier": "api", "future_field": {"keep": True}}]
            (self.tmp / "accounts.json").write_text(json.dumps(legacy), "utf-8")
            (self.tmp / "config.json").write_text(json.dumps({"port": 9999, "admin_key": "adm-x", "keys": [], "unknown_setting": 7}), "utf-8")
            cfg = Config(self.store)
