        # B3
        def test_ai_proposal_is_validated_against_evidence(self) -> None:
            evidence = 'Pick a model: Alpha One, Alpha Two\n{"id":"alpha-1"}'
            ask = lambda prompt: json.dumps({"models": [{"label": "Alpha One", "native_id": "alpha-1"}, {"label": "Phantom Ultra", "native_id": "phantom-9"},
                                                         {"label": "Alpha Two", "native_id": "made-up-id"}, "junk"]})
