        # B4
        def test_model_selection_learned_from_two_probes_and_replayed(self) -> None:
            def cap(model: str, url: str = "https://m.test/chat", hdrs: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
                return {"url": url, "headers": hdrs or {}, "body": json.dumps({"model": model, "q": "hi", "stream": True})}
            spec = derive_model_select(cap("alpha-1"), cap("alpha-2"), "alpha-1", "alpha-2")
            assert spec is not None
            self.assertEqual((spec["slot"], spec["where"]), (["body", "model"], "body.model"))
            self.assertIsNone(derive_model_select(cap("alpha-1"), cap("alpha-1"), "alpha-1", "alpha-2"))        # nothing changed -> nothing learned
            r = apply_model_select(mk_recipe(), spec)
            self.assertIsNone(validate_recipe(r))
            self.assertEqual(r["chat"]["body"]["model"], "{{model}}")
            t = FakeT(lambda m, u, b: (200, b'data: {"delta":"ok"}\n\n'))
            rc = RecipeClient(r, t, {})
            self.assertEqual("".join(rc.ask(rc.new_conv("alpha-2"), "hi")), "ok")
            self.assertEqual(json.loads(t.sent[-1]["body"])["model"], "alpha-2")                      # the chosen variant is what went on the wire
            self.assertEqual("".join(rc.ask(rc.new_conv(), "hi")), "ok")
            self.assertEqual(json.loads(t.sent[-1]["body"])["model"], "alpha-1")                      # no choice -> what the site was learned with
            # url segment and header slots
            u1, u2 = cap("same", "https://m.test/chat/alpha-1"), cap("same", "https://m.test/chat/alpha-2")
            sp = derive_model_select(u1, u2, "alpha-1", "alpha-2")
            assert sp is not None
            base = mk_recipe()
            base["chat"]["url"] = "https://m.test/chat/alpha-1"                                       # as learned from the first probe
            with self.assertRaises(ValueError):
                apply_model_select(mk_recipe(), sp)                                                   # a recipe without that segment is refused
            ru = apply_model_select(base, sp)
            self.assertEqual(ru["chat"]["url"], "https://m.test/chat/{{model}}")
            t2 = FakeT(lambda m, u, b: (200, b'data: {"delta":"ok"}\n\n'))
            list(RecipeClient(ru, t2, {}).ask(RecipeClient(ru, t2, {}).new_conv("alpha-2"), "hi"))
            self.assertEqual(t2.sent[-1]["url"], "https://m.test/chat/alpha-2")
            sh = derive_model_select(cap("s", hdrs={"x-model": "alpha-1"}), cap("s", hdrs={"x-model": "alpha-2"}), "alpha-1", "alpha-2")
            assert sh is not None
            rh = apply_model_select(mk_recipe(), sh)
            t3 = FakeT(lambda m, u, b: (200, b'data: {"delta":"ok"}\n\n'))
            list(RecipeClient(rh, t3, {}).ask(RecipeClient(rh, t3, {}).new_conv("alpha-2"), "hi"))
            self.assertEqual(t3.sent[-1]["headers"]["x-model"], "alpha-2")

        def test_model_selected_by_separate_call(self) -> None:
            r = mk_recipe(body={"q": "{{prompt}}", "chat": "{{conv.id}}"}, conv={"id": {"from": "uuid"}},
                          model_select={"kind": "set_call", "call": {"url": "https://m.test/select", "method": "POST", "headers": {"content-type": "application/json"},
                                                                   "body_kind": "json", "body": {"model": "{{model}}", "chat": "{{conv.id}}"}}})
            self.assertIsNone(validate_recipe(r))
            t = FakeT(lambda m, u, b: (200, b"{}") if u.endswith("/select") else (200, b'data: {"delta":"ok"}\n\n'))
            rc = RecipeClient(r, t, {})
            conv = rc.new_conv("alpha-2")
            self.assertEqual("".join(rc.ask(conv, "hi")), "ok")
            self.assertEqual([x["url"] for x in t.sent], ["https://m.test/select", "https://m.test/chat"])
            sel = json.loads(t.sent[0]["body"])
            self.assertEqual(sel["model"], "alpha-2")
            self.assertEqual(sel["chat"], json.loads(t.sent[1]["body"])["chat"])                      # same chat id in both requests
            with self.assertRaises(BridgeError):                                                      # cannot silently switch models mid-conversation
                list(rc.ask(conv, "hi", model="alpha-1"))
            self.assertIsNotNone(validate_recipe(mk_recipe(model_select={"kind": "set_call"})))

