        # B8 + B9
        def test_profile_follows_recipe_and_stale_profile_blocks_routing(self) -> None:
            a = add_acct(self.app, "a1", "Mock", "m.test")
            good, newer = mk_recipe(marker="good"), mk_recipe(marker="newer")
            self.acc.store_recipe(good, {"ok": True})
            self.acc.store_recipe(newer, {"ok": True})                                              # `good` goes to recipes/history
            p = self.acc.profile("m.test")
            self.assertEqual((p.status, p.submit["tier"], p.stream_format), ("ok", "direct", "sse"))
            self.assertTrue(self.store.path("profiles", "m.test.json").exists())                    # persisted
            self.assertEqual(SiteProfile.from_dict(json.loads(self.store.path("profiles", "m.test.json").read_text())).status, "ok")
            self.assertTrue(self.acc.usable(a))
            # the site starts answering 200 with a login page
            t = FakeT(lambda m, u, b: (200, b"<html><body><form>Please Sign in to continue</form></body></html>"))
            rc = RecipeClient(newer, t, {})
            with self.assertRaises(BridgeError) as cm:
                list(rc.ask(rc.new_conv(), "hi"))
            self.assertEqual(cm.exception.kind, "empty")
            self.acc.on_error(a, cm.exception)
            p = self.acc.profile("m.test")
            self.assertEqual(p.status, "stale")
            self.assertIn("login page", p.status_reason)
            self.assertEqual(p.known_failures[-1]["kind"], "login_page")
            self.assertFalse(self.acc.usable(a))                                                    # the broken recipe is not used for routing
            with self.assertRaises(BridgeError) as c1:
                self.acc.choose("", "bridge-auto")
            self.assertIn("login page", str(c1.exception))
            with self.assertRaises(BridgeError) as c2:
                self.acc.choose("", "acct:a1")
            self.assertEqual(c2.exception.kind, "setup")
            with self.assertRaises(BridgeError):
                self.acc.backend(a)
            self.assertEqual(self.acc.public()[0]["profile"]["status"], "stale")                     # surfaced to the dashboard
            # last-known-good is still there: roll back
            out = self.acc.rollback_recipe("m.test")
            self.assertTrue(out["restored_from"].startswith("m.test."))
            self.assertEqual(self.acc.recipe("m.test")["marker"], "good")
            self.assertEqual(self.store.path("recipes", "m.test.broken.json").exists(), True)
            self.assertEqual(self.acc.profile("m.test").status, "unverified")
            self.assertTrue(self.acc.usable(a))                                                     # usable again, but flagged unverified
            with self.assertRaises(BridgeError):
                self.acc.rollback_recipe("m.test")                                                  # nothing older left
            self.acc.store_recipe(mk_recipe(marker="relearned"), {"ok": True})                      # a re-learn revalidates
            self.assertEqual(self.acc.profile("m.test").status, "ok")

