        def test_unlearned_ui_preserves_the_owner_tab_if_new_chat_control_is_unavailable(self) -> None:
            from unittest import mock
            class Loc:
                def count(self): return 0
            class Page:
                url = "https://chatgpt.com/"
                def __init__(self): self.gotos = []
                def is_closed(self): return False
                def locator(self, _selector): return Loc()
                def get_by_role(self, *_args, **_kwargs): return Loc()
                def get_by_text(self, *_args, **_kwargs): return Loc()
                def inner_text(self, _selector): return "ChatGPT"
                def wait_for_timeout(self, _ms): pass
                def goto(self, url, **_kwargs): self.gotos.append(url); self.url = url
            class Browser:
                def __init__(self, page): self.page_cache = {"page": page}
                def run(self, fn, *_args): return fn(self)
            page = Page()
            be = UIBackend({"base": "https://chatgpt.com", "entry": "https://chatgpt.com/", "tier": "ui", "ui": {"diff": True}}, Browser(page))
            cancel = threading.Event()
            cancel.set()
            with mock.patch(__name__ + ".ui_type_and_send"), mock.patch(__name__ + ".ui_input_ready", return_value=True):
                list(be.ask(be.new_conv(), "hello", cancel=cancel))
            self.assertEqual(page.gotos, [])

        # -- C1: validator
        def test_validator_rejects_impossible_configs_with_precise_messages(self) -> None:
            add_acct(self.app, "d4", "Delta", "delta.test", state="login_required")
            cases = [
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:zz"]}}}, "account_missing"),
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:a1/model:nope"]}}}, "variant_unknown"),
                ({"policies": {"p": {"kind": "rotation", "members": []}}}, "empty_pool"),
                ({"policies": {"p": {"kind": "rotation", "members": ["acct:d4"]}}}, "no_eligible_member"),
                ({"policies": {"p": {"kind": "fixed", "members": ["acct:a1", "acct:b2"]}}}, "fixed_needs_one"),
                ({"policies": {"p": {"kind": "failover", "primary": "acct:a1", "backups": []}}}, "no_backups"),
                ({"policies": {"p": {"kind": "failover", "primary": "acct:a1", "backups": ["acct:a1"]}}}, "primary_in_backups"),
                ({"policies": {"p": {"kind": "magic"}}}, "unknown_kind"),
                ({"policies": {"p": {"kind": "auto"}}, "aliases": {"x": "nope"}}, "unknown_policy"),
                ({"policies": {"p": {"kind": "auto"}}, "weights": {"fast": {"load": 99}}}, "bad_weight"),
                ({"policies": {"p": {"kind": "rotation", "members": ["acct:a1"], "strategy": "dice"}}}, "bad_strategy"),
                ({"policies": {"bridge-x": {"kind": "auto"}}}, "bad_name"),
                ({"policies": {"p": {"kind": "auto"}}, "account_policy": {"gone": "p"}}, "account_missing"),
                ({"policies": {"p": {"kind": "auto", "required_capabilities": ["telepathy"]}}}, "unknown_capability"),
            ]
            for cfg_, code in cases:
                errs = self.eng.validate({**default_routing(), **cfg_})
                self.assertIn(code, [e["code"] for e in errs], (code, errs))
                self.assertTrue(all(e["message"] and e["path"] is not None for e in errs))
            self.assertEqual(self.eng.validate({**default_routing(), "policies": {"p": {"kind": "rotation", "members": ["acct:a1", "acct:b2"]}}}), [])
            before = self.eng.config()
            self.assertTrue(self.eng.save_config({"policies": {"p": {"kind": "fixed", "members": ["acct:zz"]}}}))
            self.assertEqual(self.eng.config(), before)                      # an invalid config is refused and never stored
            self.assertFalse(self.store.path("routing.json").exists())

        # -- C1: one test per policy
        def test_policy_fixed_never_substitutes(self) -> None:
            m = self.setup_policy(kind="fixed", members=["acct:b2"])
            self.acc.inflight["b2"] = 1                                       # b2 is busier than a1, a fixed route does not care
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            self.acc.get("b2")["cooldown_until"] = now() + 60
            with self.assertRaises(BridgeError) as cx:
                self.plan(m)
            self.assertIn("cooldown", str(cx.exception))
            self.assertEqual(cx.exception.kind, "unavailable")                # a1 / c3 were NOT used
            m2 = self.setup_policy("q", kind="fixed", members=["acct:b2"], on_unavailable="ask")
            with self.assertRaises(ApprovalRequired) as cx2:
                self.plan(m2)
            self.assertEqual(cx2.exception.kind, "approval_required")

        def test_explicit_rotation_pool_uses_only_the_accounts_the_owner_selected(self) -> None:
            name = self.setup_policy("user-claude-pool", kind="rotation", members=["acct:a1", "acct:b2"], strategy="round_robin", unit="request")
            first = self.plan(name)[0]["acct"]["id"]
            second = self.plan(name)[0]["acct"]["id"]
            self.assertEqual({first, second}, {"a1", "b2"})
            self.assertNotIn("c3", {first, second})

        def test_policy_auto_ranks_eligible_routes(self) -> None:
            self.acc.inflight["a1"] = 3
            r, dec = self.plan("bridge-auto")
            self.assertNotEqual(r["acct"]["id"], "a1")
            self.assertEqual((dec.policy_kind, dec.selection_basis), ("auto", "capability-based"))

        def test_policy_rotation_strategies_and_units(self) -> None:
            members = ["acct:a1", "acct:b2", "acct:c3"]
            m = self.setup_policy(kind="rotation", members=members, strategy="round_robin")
            order = [self.plan(m)[0]["acct"]["id"] for _ in range(9)]
            self.assertEqual(order, ["a1", "b2", "c3"] * 3)
            m = self.setup_policy("ll", kind="rotation", members=members, strategy="least_loaded")
            self.acc.inflight.update({"a1": 2, "b2": 0, "c3": 1})
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            self.acc.inflight.clear()
            m = self.setup_policy("lru", kind="rotation", members=members, strategy="least_recently_used")
            self.eng.lru.clear()
            self.assertEqual([self.plan(m)[0]["acct"]["id"] for _ in range(4)], ["a1", "b2", "c3", "a1"])
            m = self.setup_policy("hw", kind="rotation", members=members, strategy="health_weighted")
            self.acc.get("a1").update(ok=1, fail=9)
            self.acc.get("b2").update(ok=9, fail=1)
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")
            m = self.setup_policy("cv", kind="rotation", members=members, strategy="round_robin", unit="conversation")
            first = self.plan(m, conv="x")[0]["acct"]["id"]
            other = self.plan(m, conv="y")[0]["acct"]["id"]
            self.assertNotEqual(first, other)
            self.assertEqual(self.plan(m, conv="x")[0]["acct"]["id"], first)   # the same conversation stays on its route

        def test_policy_failover_only_uses_listed_backups(self) -> None:
            m = self.setup_policy(kind="failover", primary="acct:a1", backups=["acct:b2"])
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.fallback), ("a1", False))
            self.acc.get("a1")["cooldown_until"] = now() + 60
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.fallback), ("b2", True))
            self.acc.get("b2")["disabled"] = True
            with self.assertRaises(BridgeError):                              # c3 is healthy but was never permitted
                self.plan(m)

        def test_policy_lowest_latency_needs_samples(self) -> None:
            m = self.setup_policy(kind="lowest_latency", members=["acct:a1", "acct:b2", "acct:c3"], min_samples=3)
            r, dec = self.plan(m)
            self.assertEqual(dec.selection_basis, "capability-based")          # no latency data: not pretended
            self.assertIn("not by latency", dec.reason)
            self.acc.get("a1").update(ok=5, ema_ms=3000)
            self.acc.get("b2").update(ok=5, ema_ms=1000)
            self.acc.get("c3").update(ok=1, ema_ms=10)                         # fastest, but only one sample
            r, dec = self.plan(m)
            self.assertEqual((r["acct"]["id"], dec.selection_basis), ("b2", "measured"))
            self.assertIn("latency_samples_insufficient", [e["code"] for e in dec.excluded])

        def test_policy_best_fit_uses_capabilities_not_names(self) -> None:
            va, vb = self.var("zeta-1", image_input="supported"), self.var("omega-9")
            self.api_acct("x1", [va])
            self.api_acct("x2", [vb])
            m = self.setup_policy(kind="best_fit", members=[f"acct:x2/model:{vb.id}", f"acct:x1/model:{va.id}"], required_capabilities=["image_input"])
            r, dec = self.plan(m)
            self.assertEqual(r["acct"]["id"], "x1")                            # stated support beats unknown, whatever the order or name
            self.acc.get("x1")["cooldown_until"] = now() + 60
            r, dec = self.plan(m)
            self.assertEqual(r["acct"]["id"], "x2")
            self.assertTrue(any("image_input support unknown" in f for f in dec.flags))

        def test_policy_manual_approval_pauses_on_switch(self) -> None:
            m = self.setup_policy(kind="manual_approval", members=["acct:a1", "acct:b2"])
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "a1")             # first use is not a switch
            self.acc.get("a1")["cooldown_until"] = now() + 60
            with self.assertRaises(ApprovalRequired) as cx:
                self.plan(m)
            self.assertEqual(cx.exception.preview["to"], "acct:b2")
            self.assertEqual(self.eng.recent(1)[0]["outcome"], "approval_required")
            self.eng.approve("p", "", "acct:b2")
            self.assertEqual(self.plan(m)[0]["acct"]["id"], "b2")

        # -- C3: every exclusion reason
        def test_every_exclusion_has_a_reason_code(self) -> None:
            a1 = self.acc.get("a1")
            self.assertEqual(self.codes("acct:a1"), [])
            self.assertEqual(self.codes("acct:nope"), ["account_missing"])
            a1["disabled"] = True
            self.assertIn("account_disabled", self.codes("acct:a1"))
            a1["disabled"] = False
            a1["state"] = "learning"
            self.assertIn("account_not_ready", self.codes("acct:a1"))
            a1["state"] = "login_required"
            self.assertIn("session_expired", self.codes("acct:a1"))
            a1["state"] = "ready"
            self.acc.mark_profile("alpha.test", "stale", "login page", "login_page")
            self.assertIn("recipe_not_validated", self.codes("acct:a1"))
            self.acc.mark_profile("alpha.test", "ok", "", "")
            a1["cooldown_until"] = now() + 30
            self.assertIn("cooldown", self.codes("acct:a1"))
            a1["cooldown_until"] = 0
            self.assertIn("circuit_open", self.codes("acct:a1", breaker=lambda a: now() + 10))
            self.assertIn("failed_this_request", self.codes("acct:a1", tried={"a1"}))
            self.assertIn("policy_forbids", self.codes("acct:a1", pinned="b2"))
            self.assertIn("policy_forbids", self.codes("acct:a1", policy={"forbidden_accounts": ["a1"]}))
            self.assertIn("manually_excluded", self.codes("acct:a1", cfgd={"excluded_routes": ["acct:a1"]}))
            self.assertIn("data_transfer_forbidden", self.codes("acct:a1", policy={"data_transfer": "api_only"}))
            self.assertIn("data_transfer_forbidden", self.codes("acct:a1", policy={"data_transfer": "local_only"}))
            vok, vgone, vimg = self.var("m-ok"), self.var("m-gone", status="unavailable"), self.var("m-noimg", image_input="unsupported")
            self.api_acct("x1", [vok, vgone, vimg])
            self.assertEqual(self.codes(f"acct:x1/model:{vok.id}"), [])
            self.assertIn("variant_unknown", self.codes("acct:x1/model:ghost"))
            self.assertIn("variant_unavailable", self.codes(f"acct:x1/model:{vgone.id}"))
            cat1 = new_catalog("a1")
            cat1["variants"] = [vok.to_dict()]
            self.acc.save_catalog("a1", cat1)
            self.assertIn("variant_not_selectable", self.codes(f"acct:a1/model:{vok.id}"))        # a site account without a learned selection mechanism
            self.assertIn("capability_unsupported", self.codes(f"acct:x1/model:{vimg.id}", needs={"capabilities": ["image_input"], "tokens": 0, "max_tokens": 0}))
            self.assertNotIn("capability_unknown", self.codes(f"acct:x1/model:{vok.id}", needs={"capabilities": ["image_input"], "tokens": 0, "max_tokens": 0}))
            self.assertIn("capability_unknown", self.codes(f"acct:x1/model:{vok.id}", needs={"capabilities": ["image_input"], "tokens": 0, "max_tokens": 0},
                                                           cfgd={"strict_capabilities": True}))
            self.assertIn("context_too_large", self.codes("acct:x1", needs={"capabilities": [], "tokens": 5000, "max_tokens": 100}, cfgd={"context_windows": {"acct:x1": 1000}}))
            self.assertEqual(self.codes("acct:x1", needs={"capabilities": [], "tokens": 500, "max_tokens": 100}, cfgd={"context_windows": {"acct:x1": 1000}}), [])
            self.acc.inflight["a1"] = 99
            r, dec = self.plan("bridge-auto")
            self.assertNotEqual(r["acct"]["id"], "a1")
            self.assertIn(("acct:a1", "concurrency_cap"), [(e["route"], e["code"]) for e in dec.excluded])

        def test_default_account_strategy_is_round_robin_and_selectable(self) -> None:
            self.cfg.data["account_strategy"] = "round_robin"
            seq = [self.plan()[0]["acct"]["id"] for _ in range(7)]
            self.assertEqual(seq, ["a1", "b2", "c3", "a1", "b2", "c3", "a1"])
            self.acc.get("b2")["cooldown_until"] = now() + 60                    # a resting account is skipped, the cycle goes on
            seq2 = [self.plan()[0]["acct"]["id"] for _ in range(4)]
            self.assertEqual(seq2, ["c3", "a1", "c3", "a1"])
            self.acc.get("b2")["cooldown_until"] = 0
            self.cfg.data["rotate_every"] = 2
            self.eng.acct_rr.update({"id": "", "count": 0})
            seq3 = [self.plan()[0]["acct"]["id"] for _ in range(6)]
            self.assertEqual(seq3, ["a1", "a1", "b2", "b2", "c3", "c3"])
            self.cfg.data["account_strategy"] = "primary_first"
            self.cfg.data["default_account"] = "c3"
            self.assertEqual({self.plan()[0]["acct"]["id"] for _ in range(4)}, {"c3"})
            self.cfg.data["account_strategy"] = "least_recently_used"
            self.eng.acct_used.clear()
            self.assertEqual([self.plan()[0]["acct"]["id"] for _ in range(3)], ["a1", "b2", "c3"])

        def test_round_robin_walks_chrome_profiles_with_per_account_turn_sizes(self) -> None:
            self.cfg.data["account_strategy"] = "round_robin"
            self.cfg.data["rotate_every"] = 1
            self.cfg.data["account_quota"] = {}
            self.acc.get("a1")["pc_client_id"], self.acc.get("c3")["pc_client_id"], self.acc.get("b2")["pc_client_id"] = "P1", "P1", "P2"
            self.assertEqual(rotation_sequence(list(self.acc.items), "profile"), ["a1", "c3", "b2"])      # profile 1 completely, then profile 2
            self.assertEqual(rotation_sequence(list(self.acc.items), "spread"), ["a1", "b2", "c3"])       # one account of every profile in turn
            self.cfg.data["rotation_mode"] = "profile"
            self.eng.acct_rr.update({"id": "", "count": 0})
            self.cfg.data["account_quota"] = {"a1": 3, "c3": 2}
            seq = [self.plan()[0]["acct"]["id"] for _ in range(9)]
            self.assertEqual(seq, ["a1", "a1", "a1", "c3", "c3", "b2", "a1", "a1", "a1"])
            self.cfg.data["rotation_mode"] = "spread"
            self.eng.acct_rr.update({"id": "", "count": 0})
            seq2 = [self.plan()[0]["acct"]["id"] for _ in range(7)]
            self.assertEqual(seq2, ["a1", "a1", "a1", "b2", "c3", "c3", "a1"])

        def test_drag_and_drop_priorities_order_profiles_and_accounts(self) -> None:
            self.cfg.data.update({"account_strategy": "round_robin", "rotate_every": 1, "account_quota": {}, "rotation_mode": "profile"})
            for aid, pc in (("a1", "P1"), ("c3", "P1"), ("b2", "P2")):
                self.acc.get(aid)["pc_client_id"] = pc
            items = list(self.acc.items)
            self.assertEqual(rotation_sequence(items, "profile"), ["a1", "c3", "b2"])                                   # nothing set = the 7.84 order
            self.assertEqual(rotation_sequence(items, "profile", ["P2", "P1"]), ["b2", "a1", "c3"])                     # profile 2 first
            self.assertEqual(rotation_sequence(items, "profile", ["P2", "P1"], ["c3", "a1"]), ["b2", "c3", "a1"])       # inside profile 1 the owner put c3 first
            self.assertEqual(rotation_sequence(items, "spread", ["P2", "P1"], ["c3"]), ["b2", "c3", "a1"])
            self.assertEqual(rotation_sequence(items, "profile", ["nope", "P2"], ["ghost"]), ["b2", "a1", "c3"])        # unknown ids are harmless
            self.assertEqual(rotation_sequence(items, "profile", "garbage", None), ["a1", "c3", "b2"])                  # a damaged file never breaks routing
            self.assertEqual(_clean_order(["x", "x", "", 5, "y" * 500, "z"]), ["x", "5", "z"])
            self.cfg.data["profile_order"], self.cfg.data["account_order"] = ["P2", "P1"], ["c3", "a1"]
            self.eng.acct_rr.update({"id": "", "count": 0})
            self.assertEqual([self.plan()[0]["acct"]["id"] for _ in range(5)], ["b2", "c3", "a1", "b2", "c3"])           # the round robin follows the priorities
            self.cfg.data["account_strategy"] = "priority_order"
            self.assertEqual([self.plan()[0]["acct"]["id"] for _ in range(3)], ["b2", "b2", "b2"])                      # always the first one in priority order

        def test_site_ui_learning_checks_the_choice_against_the_real_exchange(self) -> None:
            prompt, answer = "Please summarise the quarterly report for me", "Sure - here is a short summary of the quarterly report."
            snap = {"cands": [
                {"i": 0, "hint": "input", "sel": "textarea", "vis": 1, "editable": True},
                {"i": 1, "hint": "button", "sel": '[data-testid="send-button"]', "vis": 1, "label": "Send message", "head": ""},
                {"i": 2, "hint": "button", "sel": 'button[aria-label="Delete chat"]', "vis": 1, "label": "Delete chat", "head": ""},
                {"i": 3, "hint": "message", "sel": '[data-role="user"]', "n": 1, "head": prompt[:20], "full": prompt, "tail": prompt},
                {"i": 4, "hint": "message", "sel": '[data-role="assistant"]', "n": 1, "head": answer[:20], "full": answer, "tail": answer},
                {"i": 5, "hint": "message", "sel": '[data-testid="conversation"]', "n": 1, "head": prompt[:20], "full": prompt + " " + answer, "tail": answer}]}
            good = {"input": 0, "send": 1, "user_msg": 3, "assistant_msg": 4}
            sel, why = ui_learn_validate(good, snap, prompt, answer)
            self.assertEqual(sel, {"input": "textarea", "send": '[data-testid="send-button"]', "user_msg": '[data-role="user"]', "assistant_msg": '[data-role="assistant"]'})
            self.assertEqual(why, [])
            sel, why = ui_learn_validate({**good, "send": 2}, snap, prompt, answer)                  # a delete button is never a send button
            self.assertNotIn("send", sel)
            self.assertTrue(any(w.startswith("send") for w in why))
            self.assertNotIn("assistant_msg", ui_learn_validate({**good, "assistant_msg": 5}, snap, prompt, answer)[0])   # the whole conversation is not one answer
            self.assertNotIn("user_msg", ui_learn_validate({**good, "user_msg": 5}, snap, prompt, answer)[0])
            self.assertNotIn("assistant_msg", ui_learn_validate({**good, "assistant_msg": 3}, snap, prompt, answer)[0])   # the user's bubble is not the answer
            self.assertEqual(ui_learn_validate({**good, "input": 99}, snap, prompt, answer)[0], {})                       # not a number from the list: nothing is learned
            self.assertNotIn("send", ui_learn_validate({**good, "send": True}, snap, prompt, answer)[0])                  # a boolean is not an index

        def test_site_ui_profile_is_a_first_choice_verified_by_use_and_dropped_when_stale(self) -> None:
            ui, h = SiteUIProfiles(), "chat.example.test"
            ui.bind(self.cfg, self.store)
            self.assertEqual(ui.sel(h, "input"), "")
            ui._save(h, {"host": h, "status": "learned", "selectors": {"input": "textarea", "send": "x; drop table"}, "strikes": 0})
            self.assertEqual(ui.sel(h, "input"), "textarea")
            self.assertEqual(ui.sel(h, "send"), "")                                                  # anything that is not a plain attribute selector is never used
            ui.note_used_host(h, "input")
            ui.success(h)
            self.assertEqual(ui.get(h)["status"], "verified")

            class Pg:
                url = "https://chat.example.test/c/1"
            for _ in range(UI_PROFILE_STRIKES_MAX):
                ui.strike_page(Pg(), "input")
            self.assertEqual(ui.sel(h, "input"), "")                                                 # stale: the generic rules are in charge again
            ui2 = SiteUIProfiles()
            ui2.bind(self.cfg, self.store)
            self.assertEqual(ui2.get(h)["status"], "stale")                                          # and it survives a restart
            self.assertTrue(ui2.forget(h))
            self.assertEqual([s for s in ui2.view() if s["host"] == h], [])
            self.cfg.data["site_ui_learning"] = False
            self.assertFalse(ui.want_learning("new.example.test"))
            self.cfg.data.update({"site_ui_learning": True, "advisor_enabled": True})
            self.assertTrue(ui.want_learning("new.example.test"))
            ui._save("new.example.test", {"host": "new.example.test", "status": "rejected", "attempts": [now()] * 3})
            self.assertFalse(ui.want_learning("new.example.test"))                                   # the daily budget for this site is used up

        def test_site_ui_learning_end_to_end_with_a_fake_advisor_keeps_conversation_text_local(self) -> None:
            prompt, answer, h = "Please summarise the quarterly report for me", "Sure - here is a short summary of the quarterly report.", "chat2.example.test"
            snap = {"url": "https://chat2.example.test/c/1", "title": "Chat", "cands": [
                {"i": 0, "hint": "input", "sel": "textarea", "vis": 1, "editable": True},
                {"i": 1, "hint": "message", "sel": '[data-role="user"]', "n": 1, "head": prompt[:20], "full": prompt, "tail": prompt},
                {"i": 2, "hint": "message", "sel": '[data-role="assistant"]', "n": 1, "head": answer[:20], "full": answer, "tail": answer}]}
            seen: List[str] = []

            class FakeAdv:
                def ask(self, task, sections, schema, instruction, exclude=()):
                    seen.append(json.dumps(sections))
                    return {"input": 0, "send": None, "user_msg": 1, "assistant_msg": 2, "confidence": 0.9, "reason": "clear"}
            ui = SiteUIProfiles()
            ui.bind(self.cfg, self.store)
            saved = list(ADVISOR)
            ADVISOR[:] = [FakeAdv()]
            try:
                ui.busy.add(h)
                ui._learn(h, [h], snap, prompt, answer, "")
            finally:
                ADVISOR[:] = saved
            rec = ui.get(h) or {}
            self.assertEqual(rec.get("status"), "learned")
            self.assertEqual(rec["selectors"], {"input": "textarea", "user_msg": '[data-role="user"]', "assistant_msg": '[data-role="assistant"]'})
            self.assertNotIn(h, ui.busy)
            self.assertNotIn(prompt, seen[0])                                                        # only the start of a message goes to the model, never the whole text
            self.assertNotIn("quarterly report.", seen[0])

        def test_advisor_decisions_are_validated_and_fall_back_to_none(self) -> None:
            class FakeAdv:
                def __init__(self, data: Any):
                    self.data = data
                    self.seen: List[Any] = []

                def ask(self, task: str, sections: Any, schema: Any, instruction: str, exclude: Any = ()) -> Any:
                    self.seen.append((task, list(exclude)))
                    return self.data
            snap = {"text": "Messages too frequent. Try again later.", "controls": [{"i": 0, "text": "", "label": "", "svg": True}, {"i": 1, "text": "Delete chat", "label": ""}]}
            old = list(ADVISOR)
            try:
                ADVISOR[:] = [FakeAdv({"situation": "rate_limited", "confidence": 0.9, "action": "click_control", "wait_seconds": 20, "control_index": 0, "reason": "retry icon"})]
                r = advise_stall(snap, 30, "", "a1")
                self.assertEqual((r["action"], r["control_index"], r["wait_seconds"]), ("click_control", 0, 20.0))
                self.assertEqual(ADVISOR[0].seen[0][1], ["a1"])                          # the stuck account is never asked
                ADVISOR[:] = [FakeAdv({"situation": "x", "confidence": 5, "action": "click_control", "wait_seconds": 9999, "control_index": 1, "reason": "r"})]
                r = advise_stall(snap, 30, "", "a1")                                    # unknown situation, unsafe control (Delete), clamped numbers
                self.assertEqual((r["situation"], r["action"], r["control_index"], r["wait_seconds"], r["confidence"]), ("unknown", "wait", None, 9999.0 if False else 300.0, 1.0))
                ADVISOR[:] = [FakeAdv({"situation": "error", "confidence": 1, "action": "format_disk", "wait_seconds": 1, "control_index": None, "reason": "r"})]
                self.assertIsNone(advise_stall(snap, 30, "", "a1"))                     # an action outside the allow-list is refused
                ADVISOR[:] = [FakeAdv(None)]
                self.assertIsNone(advise_stall(snap, 30, "", "a1"))                     # no answer -> the caller uses its built-in rules
                ADVISOR[:] = []
                self.assertIsNone(advise_stall(snap, 30, "", "a1"))
            finally:
                ADVISOR[:] = old

        def test_advisor_never_asks_the_stuck_account_and_not_while_answering(self) -> None:
            self.cfg.data["advisor_enabled"] = True
            adv = Advisor(self.app)
            self.assertEqual(adv._pick({"a1", "b2"}), "c3")
            self.assertEqual(adv._pick({"a1", "b2", "c3"}), "")                          # nobody else: no question, the caller falls back
            self.acc.get("c3")["cooldown_until"] = now() + 60
            self.assertEqual(adv._pick({"a1", "b2"}), "")                                # a resting account is not asked
            _ADV_TLS.active = True
            try:
                self.assertIsNone(adv.ask("t", [("x", "y")], {"a": "str"}, "i", exclude=["a1"]))   # no advisor question from inside an advisor question
            finally:
                _ADV_TLS.active = False

        def test_no_eligible_route_explains_every_candidate(self) -> None:
            self.acc.get("a1")["disabled"] = True
            self.acc.get("b2")["cooldown_until"] = now() + 60
            self.acc.get("c3")["state"] = "login_required"
            self.app.router.cfg.data["cooldown_wait_max_seconds"] = 0
            with self.assertRaises(BridgeError) as cx:
                self.plan("bridge-auto")
            msg = str(cx.exception)
            for rid, code in (("acct:a1", "account_disabled"), ("acct:b2", "cooldown"), ("acct:c3", "session_expired")):
                self.assertIn(rid, msg)
                self.assertIn(code, msg)
            with self.assertRaises(BridgeError) as cx2:                         # through the router the established kind survives and the reasons are appended
                self.app.router.handle(self.mkreq(), lambda t: None, "", threading.Event(), scope="k", meta={"request_id": "req_x"})
            self.assertIn("Excluded", str(cx2.exception))

        # -- C2: execution profiles
        def test_profiles_rank_by_fabricated_telemetry_and_stay_neutral_without_it(self) -> None:
            self.assertEqual(self.plan("bridge-auto")[1].selection_basis, "capability-based")
            self.acc.get("a1").update(ok=50, fail=0, ema_ms=9000)               # reliable but slow
            self.acc.get("b2").update(ok=50, fail=25, ema_ms=500)               # fast but flakier
            self.acc.get("c3")["disabled"] = True
            pick = {m: self.plan(m)[0]["acct"]["id"] for m in ("bridge-fast", "bridge-balanced", "bridge-quality")}
            self.assertEqual(pick, {"bridge-fast": "b2", "bridge-balanced": "b2", "bridge-quality": "a1"})
            self.assertEqual(self.plan("bridge-quality")[1].selection_basis, "measured")
            self.assertEqual(self.plan("bridge-fast")[1].profile, "fast")
            for a in ("a1", "b2"):
                self.acc.get(a).update(ok=0, fail=0, ema_ms=0)
            self.assertEqual({self.plan(m)[0]["acct"]["id"] for m in ("bridge-fast", "bridge-balanced", "bridge-quality")}, {"a1"})   # unknown = neutral, same result
            self.cfg.data["default_account"] = "b2"
            self.assertEqual(self.plan("bridge-quality")[0]["acct"]["id"], "b2")      # neutral ties fall back to the previous tested order

        def test_weights_are_bounded_and_pins_win_over_profiles(self) -> None:
            self.store.write("routing.json", {**default_routing(), "weights": {"fast": {"load": 1e9, "latency": -5}}})
            w = self.eng.weights("fast", self.eng.config())
            self.assertEqual((w["load"], w["latency"]), (WEIGHT_MAX, 0.0))
            self.acc.get("a1").update(ok=50, fail=25, ema_ms=9000)
            self.acc.get("b2").update(ok=50, fail=0, ema_ms=100)
            r, dec = self.plan("bridge-fast", pinned="a1")                      # a key pinned to a1: the fast profile cannot move it
            self.assertEqual((r["acct"]["id"], dec.policy_kind), ("a1", "fixed"))
            with self.assertRaises(BridgeError):
                self.plan("acct:b2", pinned="a1")

        # -- C6: decisions + headers
        def test_decisions_and_headers_on_success_and_failure(self) -> None:
            self.app.router.handle(self.mkreq(), lambda t: None, "", threading.Event(), scope="k", meta={"request_id": "req_ok1"})
            d = self.eng.recent(1)[0]
            self.assertEqual((d["request_id"], d["outcome"], d["policy"], d["fallback"]), ("req_ok1", "ok", "implicit-auto", False))
            self.assertTrue(d["selected"]["route"].startswith("acct:") and d["timings"]["total_ms"] >= 0 and d["requested_model"] == "bridge-auto")
            self.assertNotIn("sk-bridge", json.dumps(self.eng.recent(50)))      # secret-free by construction
            srv = Server(self.app)
            try:
                H = {"x-api-key": self.cfg.data["keys"][0]["key"]}
                body = {"model": "claude-sonnet-x", "max_tokens": 50, "messages": [{"role": "user", "content": "hi"}]}
                for stream in (False, True):
                    st, hdr, _b = call(srv.port, "POST", "/v1/messages", {**body, "stream": stream}, H)
                    self.assertEqual(st, 200)
                    self.assertIn(hdr["x-bridge-account"], ("a1", "b2", "c3"))
                    self.assertEqual((hdr["x-bridge-route"], hdr["x-bridge-model"], hdr["x-bridge-fallback"]), ("acct:" + hdr["x-bridge-account"], "account-default", "false"))
                    self.assertTrue(hdr["x-bridge-request-id"].startswith("req_") and hdr["x-bridge-policy"].startswith("implicit-auto"))
                    self.assertEqual(hdr["x-bridge-model-identity"], "unknown")
                pk = self.cfg.add_key("pin", "a1")["key"]
                self.acc.get("a1")["cooldown_until"] = now() + 60
                st, hdr, b = call(srv.port, "POST", "/v1/messages", body, {"x-api-key": pk})
                self.assertEqual(st, 429)                                        # failure path: same kind as before, with route headers and a stored decision
                self.assertIn("x-bridge-policy", hdr)
                self.assertEqual(self.eng.recent(1)[0]["outcome"], "no_eligible_route")
                st, _h, b = call(srv.port, "GET", "/api/decisions?n=5", headers={"x-admin-key": self.cfg["admin_key"]})
                self.assertEqual((st, len(json.loads(b)["decisions"]) > 0), (200, True))
            finally:
                srv.close()

        def test_owner_can_disable_an_account_and_it_persists(self) -> None:
            srv = Server(self.app)
            try:
                A = {"x-admin-key": self.cfg["admin_key"]}
                self.assertEqual(call(srv.port, "POST", "/api/accounts/a1/enabled", {"enabled": False}, A)[0], 200)
                self.assertEqual(call(srv.port, "POST", "/api/accounts/zz/enabled", {"enabled": False}, A)[0], 404)
                r, dec = self.plan("bridge-auto")
                self.assertNotEqual(r["acct"]["id"], "a1")
                self.assertIn(("acct:a1", "account_disabled"), [(e["route"], e["code"]) for e in dec.excluded])
                saved = json.loads(self.store.path("accounts.json").read_text("utf-8"))
                self.assertTrue(any(x["id"] == "a1" and x.get("disabled") for x in (saved if isinstance(saved, list) else saved.get("items", saved.get("accounts", [])))))
                self.assertEqual(call(srv.port, "POST", "/api/accounts/a1/enabled", {"enabled": True}, A)[0], 200)
                self.assertFalse(self.acc.get("a1").get("disabled"))
            finally:
                srv.close()

