        def test_v1_models_is_a_real_catalog_with_status_and_confidence(self) -> None:
            self.cfg.add_key("open", "")
            self.policies()
            body = self.models()
            ids = [m["id"] for m in body["data"]]
            self.assertEqual(ids[:4], ["bridge-auto", "acct:a1", "acct:b2", "acct:c3"])
            for must in ("use-p", "bridge-pool/p", "bridge-pool/pin1", "acct:a1/model:" + self.v["alpha-1"], "acct:a1/model:" + self.v["alpha-2"],
                         "acct:b2/model:" + self.v["alpha-2"], "acct:b2/model:" + self.v["beta-1"]):
                self.assertIn(must, ids)
            self.assertNotIn("acct:a1/model:" + self.v["alpha-3"], ids)             # unavailable: not selectable
            self.assertFalse([i for i in ids if "mystery" in i])                     # no native id -> the bridge cannot choose it -> not offered
            self.assertEqual(body["x_bridge"]["unselectable_variants"], {"a1": 1})  # ... but the gap is stated, not hidden
            by = {m["id"]: m for m in body["data"]}
            v = by["acct:b2/model:" + self.v["beta-1"]]["x_bridge"]
            self.assertEqual((v["kind"], v["status"], v["confidence"], v["stale"], v["native_id"], v["model_identity"]), ("variant", "stale", "observed", True, "beta-1", "unknown"))
            self.assertEqual(v["capabilities"]["image_input"], "supported")
            self.assertEqual(v["capabilities"]["streaming"], "unknown")             # nothing is promoted to 'supported' without evidence
            self.assertEqual(by["acct:a1"]["x_bridge"]["variants"], 4)
            self.assertEqual(by["bridge-pool/p"]["x_bridge"]["policy_kind"], "auto")
            self.assertEqual(body["x_bridge"]["documented_aliases"], ["bridge-auto", "bridge-fast", "bridge-balanced", "bridge-quality"])

        def test_v1_models_never_lists_what_the_key_cannot_use(self) -> None:
            self.policies()
            self.assertEqual(self.eng.save_config({"policies": {"only_b": {"kind": "fixed", "members": ["acct:b2"]}, "p": {"kind": "auto"}}, "aliases": {"bonly": "only_b"}}), [])
            k = self.cfg.add_key("pinned-a1", "a1")
