                d = json.loads(body)
                self.assertEqual(st, 429)
                self.assertEqual(h["x-bridge-error-category"], "usage_cap_account")
                self.assertEqual((h["x-bridge-error-scope"], h["x-bridge-retryable"], h["retry-after"]), ("account", "true", "120"))
                self.assertEqual(d["x_bridge"]["error"]["category"], "usage_cap_account")
                self.assertTrue(d["x_bridge"]["error"]["limit_confirmed"])
                st, h, body = call(port, "POST", "/v1/messages", {"model": "bridge-auto", "max_tokens": 10, "messages": [{"role": "user", "content": "hi"}]}, {"x-api-key": key})
                self.assertEqual(st, 429)                                                      # still resting: typed no-route error, with a wait
                self.assertEqual(json.loads(body)["x_bridge"]["error"]["category"], "usage_cap_account")
                self.assertTrue(int(h["retry-after"]) > 0)
