        # -- E3 (7.12): a per-route window learned only from the site's own refusals ----------------------------------------------------
        def _refusing_site(self, limit: int = 5000, code: int = 413) -> Tuple[Dict[str, Any], List[int]]:
            seen: List[int] = []

            def responder(m: str, u: str, b: Optional[bytes]) -> Tuple[int, bytes]:
                q = json.loads(b)["q"]
                seen.append(len(q))
                return (code, b"payload too large") if len(q) > limit else (200, b'data: {"delta":"ok"}\n\n')
            rec = mk_recipe("alpha.test")
            self._site(rec, responder)
            return rec, seen

        def test_a_refusal_teaches_the_route_window_and_it_is_reported_as_learned(self) -> None:
            rec, seen = self._refusing_site()
            self.run_req(self.req())
            rw = self.app.acc.profile("alpha.test").long_paste["route_windows"]["acct:a1"]
            self.assertEqual(rw["rejected_chars"], min(x for x in seen if x > 5000))      # the smallest size the site refused
            self.assertGreater(rw["accepted_chars"], 0)                           # a smaller request the site then answered
            self.assertLess(rw["accepted_chars"], rw["rejected_chars"])
            lw = self.rt.context_report()["learned_windows"]
            self.assertEqual((lw[0]["route"], lw[0]["chars"], lw[0]["label"]), ("acct:a1", rw["accepted_chars"], "learned"))
            n = len(seen)
            self.run_req(self.req(tag="n"))                                       # the next task is built inside the learned window straight away: no new refusal
            self.assertEqual(len(seen) - n, 1)
            self.assertLessEqual(seen[-1], 5000)
            self.assertEqual(self.rt.context_report()["recent"][0]["submission"]["learned_window_chars"], rw["accepted_chars"])
            json.dumps(rw)

        def test_a_declared_window_wins_and_without_a_structured_refusal_nothing_is_learned(self) -> None:
            self.store.write("routing.json", {"context_windows": {"acct:a1": 40000}})
            rec, seen = self._refusing_site()
            self.run_req(self.req())
            sub = self.rt.context_report()["recent"][0]["submission"]
            self.assertNotIn("learned_window_chars", sub)                         # the declared window is the budget; a learned one never replaces it
            self.store.write("routing.json", {})
            rec2, seen2 = self._refusing_site(limit=0, code=500)                  # a plain server error is not a context refusal
            before = json.dumps(self.app.acc.profile("alpha.test").long_paste.get("route_windows") or {}, sort_keys=True)
            with self.assertRaises(BridgeError):
                self.run_req(self.req(tag="z"))
            self.assertEqual(json.dumps(self.app.acc.profile("alpha.test").long_paste.get("route_windows") or {}, sort_keys=True), before)

        def double(self, record: List[str]) -> Any:
            class BE:
                tier, fenced_tools = "direct", False

                def new_conv(self, model: Optional[str] = None) -> Dict[str, Any]:
                    return {"n": 1}

                def ask(self, conv: Any, prompt: str, cancel: Any = None, model: str = "") -> Iterator[str]:
                    record.append(prompt)
                    if len(prompt) > 3000:
                        conv["paste"] = {"converted": True, "kind": "attachment", "evidence": "double"}
                    yield "OK" if prompt.startswith("[bridge: part") and "do not answer yet" in prompt else "answer"
            return BE()

        def test_split_needs_the_profile_to_say_it_works_attach_is_capped_and_error_sends_nothing(self) -> None:
            sent: List[str] = []
            self.app.acc.backend = lambda a: self.double(sent)                    # type: ignore[assignment]
            self.cfg.data["paste_limit_chars"] = 3000
            self.cfg.data["paste_policy"] = "split"
            rec = mk_recipe("alpha.test")
            self.app.acc.recipe = lambda host: rec                                # type: ignore[assignment]
            self.run_req(self.req())                                              # the profile does not say split works -> reduced instead, and the decision says why
            sub = self.rt.context_report()["recent"][0]["submission"]
            self.assertEqual(sub["action"], "reduced")
            self.assertIn("split_unavailable", sub)
            self.assertTrue(all(len(x) <= 3000 for x in sent), [len(x) for x in sent])
            rec["long_paste"] = {"split": True}
            sent.clear()
            big = self.req(n_turns=1, size=100)
            big.messages[0]["content"] = [{"type": "text", "text": "\n\n".join(f"paragraph {i}: " + "x" * 700 for i in range(12))}]
            self.run_req(big)
            self.assertGreaterEqual(len(sent), 3)
            self.assertTrue(all(len(x) <= 3000 for x in sent))
            self.assertIn("do not answer yet", sent[0])
            self.assertIn("the message is complete now", sent[-1])
            self.assertEqual(self.rt.context_report()["measured"]["paste_parts_sent"], len(sent) - 1)                # extra upstream requests are counted
            self.assertIn("paragraph 11:", "".join(sent))                                                          # nothing dropped
            self.cfg.data["paste_policy"], rec["long_paste"] = "attach", {}
            self.cfg.data["paste_uploads_max"] = 1
            sent.clear()
            big2 = self.req(n_turns=1, size=100)
            big2.messages[-1]["content"] = [{"type": "text", "text": "y" * 4000}]
            self.run_req(big2)                                                    # allowed, the site reports the conversion, it is counted
            self.assertEqual(len(sent), 1)
            with self.assertRaises(BridgeError) as cx:
                self.run_req(big2)
            self.assertEqual((cx.exception.kind, len(sent)), ("context_too_large", 1))                            # capped: explicit error, nothing sent
            self.cfg.data["paste_policy"] = "error"
            with self.assertRaises(BridgeError):
                self.run_req(big2)
            self.assertEqual(len(sent), 1)

        # -- E2: canonical signatures -----------------------------------------------------------------------------------------------
        def test_signatures_are_unambiguous_cover_every_block_kind_and_see_the_tail(self) -> None:
            U = lambda *b: {"role": "user", "content": list(b)}                  # noqa: E731
            T = lambda t: {"type": "text", "text": t}                            # noqa: E731
            call = {"type": "tool_use", "id": "x", "name": "Bash", "input": {"b": 1, "a": 2}}
            self.assertEqual(msg_sig(U(T("ab"), T("c"))), msg_sig(U(T("abc"))))                                      # the site sees one text
            self.assertEqual(msg_sig(U({**call, "id": "other"})), msg_sig(U({**call, "input": {"a": 2, "b": 1}})))   # ids/key order are not identity
            distinct = [U(T("a|U:Bash{}")), U(T("a"), {**call, "input": {}}), U(T("a"), {**call, "name": "Read", "input": {}}),
                        U({"type": "tool_result", "tool_use_id": "x", "content": "boom"}), U({"type": "tool_result", "tool_use_id": "x", "content": "boom", "is_error": True}),
                        U({"type": "thinking", "thinking": "plan A"}), U({"type": "thinking", "thinking": "plan B"}), U({"type": "mystery", "v": 1}), U({"type": "mystery", "v": 2}),
                        U(T("head " * 40000 + "tail-1")), U(T("head " * 40000 + "tail-2")), {"role": "assistant", "content": [T("a")]}, U(T("a")), U(T("a"), T("b"), {**call, "input": {}}),
                        U({**call, "input": {}}, T("a"), T("b"))]
            sigs = [msg_sig(m) for m in distinct]
            self.assertEqual(len(set(sigs)), len(sigs))
            tools = lambda *t: sha(jdump({n: (d, sch) for n, d, sch in t}))      # noqa: E731
            self.assertEqual(tools(("A", "d", {"x": 1}), ("B", "d", {})), tools(("B", "d", {}), ("A", "d", {"x": 1})))          # reordered tools: same set, same signature
            self.assertNotEqual(tools(("A", "d", {"x": 1})), tools(("A", "d", {"x": 2})))                                      # a changed schema is not
            self.assertNotEqual(sha("system one"), sha("system one "))                                                          # nor is a changed system prompt

