        # ---------------------------------------------------------------- O3
        def _flow(self, snaps: List[Dict[str, Any]], pre: Optional[Dict[str, Any]] = None, start: str = "https://s.test/login") -> List[Dict[str, Any]]:
            w = LoginWatcher(pre or {"cookies": {}, "storage": {}}, start)
            return [w.observe(x) for x in snaps]

        def test_o3_four_mock_login_flows_succeed_only_with_two_signals_held_twice(self) -> None:
            login = {"url": "https://s.test/login", "password_visible": True}
            flows = {
                "cookie login": [login, {"url": "https://s.test/chat", "cookies": {"s.test|session_id": "a1"}, "chat_input": True}] * 1
                                + [{"url": "https://s.test/chat", "cookies": {"s.test|session_id": "a1"}, "chat_input": True}],
                "token in storage": [login, {"url": "https://s.test/app", "storage": {"access_token": "t1"}, "profile_xhr": True},
                                     {"url": "https://s.test/app", "storage": {"access_token": "t1"}, "profile_xhr": True}],
                "SSO redirect": [{"url": "https://accounts.sso.example/login", "password_visible": True},
                                 {"url": "https://s.test/chat", "chat_input": True}, {"url": "https://s.test/chat", "chat_input": True}],
                "login page returned with HTTP 200": [login, {"url": "https://s.test/", "password_visible": True}, {"url": "https://s.test/", "cookies": {"s.test|sid": "z"}, "chat_input": True},
                                                      {"url": "https://s.test/", "cookies": {"s.test|sid": "z"}, "chat_input": True}],
            }
            for name, snaps in flows.items():
                res = self._flow(snaps, start="https://s.test/login" if name != "SSO redirect" else "https://accounts.sso.example/login")
                flags = [r["success"] for r in res]
                self.assertFalse(flags[0], name)                       # the login page alone is never a login
                self.assertTrue(flags[-1], name)
                self.assertEqual(flags.index(True), len(flags) - 1, name)        # accepted at the second qualifying look, not the first
                self.assertEqual(res[-1]["by"], "signals", name)

        def test_o3_one_signal_is_never_enough_a_flap_resets_and_the_owner_button_always_works(self) -> None:
            only_a = {"url": "https://s.test/login", "cookies": {"s.test|auth_token": "x"}, "password_visible": True}
            only_b = {"url": "https://s.test/login", "chat_input": True}
            only_c = {"url": "https://s.test/login", "profile_xhr": True, "password_visible": True}
            for one in (only_a, only_b, only_c):
                self.assertFalse(any(r["success"] for r in self._flow([one] * 6)))
            two = {"url": "https://s.test/chat", "cookies": {"s.test|auth_token": "x"}, "chat_input": True}
            res = self._flow([two, only_b, two, only_b, two])
            self.assertFalse(any(r["success"] for r in res))                  # flapping never reaches two looks in a row
            w = LoginWatcher({}, "https://s.test/login")
            w.mark_done()
            r = w.observe({"url": "https://s.test/login", "password_visible": True, "challenge": {"kind": "captcha"}})
            self.assertTrue(r["success"])
            self.assertEqual(r["by"], "owner_button")

        def test_o3_a_challenge_blocks_the_automatic_decision(self) -> None:
            two = {"url": "https://s.test/chat", "cookies": {"s.test|auth_token": "x"}, "chat_input": True, "challenge": {"kind": "captcha"}}
            self.assertFalse(any(r["success"] for r in self._flow([two] * 5)))
            self.assertTrue(self._flow([two, {**two, "challenge": None}, {**two, "challenge": None}])[-1]["success"])

        def test_o3_signal_helpers(self) -> None:
            pre = {"cookies": {"s|session_id": "A", "s|theme": "d"}, "storage": {"access_token": "T1"}}
            post = {"cookies": {"s|session_id": "B", "s|theme": "l", "s|csrf_token": "n"}, "storage": {"access_token": "T1", "last_page": "x"}}
            self.assertEqual(sorted(auth_changes(pre, post)), ["cookies:s|csrf_token", "cookies:s|session_id"])       # changed/new auth-looking names only; theme and last_page ignored
            self.assertFalse(auth_changes(post, post))
            self.assertTrue(profile_like_json('{"user": {"email": "a@b.c", "name": "A"}}'))
            self.assertTrue(profile_like_json({"email": "a@b.c", "id": 7}))
            self.assertFalse(profile_like_json('{"user": null}'))
            self.assertFalse(profile_like_json('{"models": ["a", "b"]}'))
            self.assertFalse(profile_like_json("<html>"))
            for u, v in (("https://s.test/login", True), ("https://s.test/auth/callback", True), ("https://auth.s.test/", True), ("https://s.test/chat", False), ("https://s.test/", False)):
                self.assertEqual(url_on_login_path(u), v, u)
            self.assertTrue(is_window_closed_error(RuntimeError("Target page, context or browser has been closed")))
            self.assertFalse(is_window_closed_error(RuntimeError("login was not completed in time")))

        def test_o3_an_account_is_logged_in_exactly_once_per_run(self) -> None:
            self.acc._job_main = lambda acct, job: None                              # the real start_job (it opens a new run); only the browser thread body is skipped
            a, _j = self.acc.add("https://once.example", "Once")
            res = self._flow([{"url": "https://once.example/chat", "cookies": {"x|auth": "1"}, "chat_input": True}] * 2)[-1]
            self.assertTrue(self.acc.finish_login(a["id"], res))
            self.assertFalse(self.acc.finish_login(a["id"], res))
            self.assertEqual(len(self.acc.items), 1)
            self.assertEqual([e["to"] for e in a["lifecycle"]["events"]].count("capturing"), 1)
            self.assertIn("auth_state_changed", a["login"]["signals"])
            self.acc.start_job(a, "login")                                          # a new login run (re-login) is accepted again
            self.assertTrue(self.acc.finish_login(a["id"], res))

        def _run_job(self, a: Dict[str, Any], exc: BaseException) -> Job:
            job = Job("login", a["label"])
            def boom() -> None:
                raise exc
            old = globals()["ensure_playwright"]
            globals()["ensure_playwright"] = boom
            try:
                self.acc._job_main(a, job)
            finally:
                globals()["ensure_playwright"] = old
            return job

        def test_o3_closing_the_window_early_is_a_clean_abort_never_a_half_created_account(self) -> None:
            self.acc.start_job = lambda a, k, **kw: Job(k, a["label"])
            a, _j = self.acc.add("https://early.example", "Early")
            self.store.path("profiles", a["id"]).mkdir(parents=True, exist_ok=True)
            job = self._run_job(a, RuntimeError("Target page, context or browser has been closed"))
            self.assertEqual(job.aborted, "removed")
            self.assertIsNone(self.acc.get(a["id"]))
            self.assertFalse(self.store.path("profiles", a["id"]).exists())
            self.assertEqual(json.loads(self.store.path("accounts.json").read_text()), [])
            self.assertTrue(any("not created" in ln for ln in job.lines))
            # an account that had logged in before keeps its data and only needs a new login
            b = self.mk("old1", "degraded_fallback", state="ready")
            self.sess("old1")
            job = self._run_job(b, RuntimeError("Target page, context or browser has been closed"))
            self.assertEqual(job.aborted, "needs_login")
            self.assertEqual(self.acc.get("old1")["lifecycle"]["state"], "needs_login")
            self.assertTrue(self.acc.session("old1")["cookies"])
            # a timeout is reported and the account stays, with the reason, so the owner can retry
            c = self.mk("slow1", "logging_in", state="learning")
            job = self._run_job(c, BridgeError("login was not completed in time", "login", 408))
            self.assertEqual(job.aborted, "")
            self.assertEqual(self.acc.get("slow1")["lifecycle"]["state"], "needs_login")
            self.assertIn("not completed in time", self.acc.get("slow1")["lifecycle"]["reason"])

        def test_o3_the_owner_button_reaches_the_running_job(self) -> None:
            self.mk("j1", "logging_in", state="learning")
            job = Job("login", "x")
            self.acc.jobs[job.id] = job
            srv = Server(self.app)
            try:
                H = {"x-admin-key": self.cfg["admin_key"]}
                self.assertEqual(call(srv.port, "POST", f"/api/jobs/{job.id}/done", {}, H)[0], 200)
                self.assertTrue(job.user_done)
                self.assertEqual(call(srv.port, "POST", "/api/jobs/nope/done", {}, H)[0], 404)
            finally:
                srv.close()

        # ---------------------------------------------------------------- O7
        def test_o7_challenge_table(self) -> None:
            cases = [({"title": "Just a moment..."}, "bot_check"), ({"text": "Please verify you are human to continue"}, "bot_check"),
                     ({"text": '<div class="g-recaptcha"></div> solve it'}, "captcha"), ({"text": "Cloudflare Turnstile widget"}, "captcha"),
                     ({"headers": {"CF-Mitigated": "challenge"}}, "bot_check"), ({"text": "Enter the 6-digit code we sent you"}, "mfa"),
                     ({"text": "Two-factor authentication required"}, "mfa")]
            for kw, kind in cases:
                r = detect_challenge(**kw)
                self.assertIsNotNone(r, kw)
                self.assertEqual(r["kind"], kind, kw)
            self.assertIsNone(detect_challenge(200, {}, "New chat", "Hello! How can I help you today? Ask me anything.", "https://s.test/chat"))
            self.assertIsNone(detect_challenge())

        def test_o7_a_challenge_takes_the_account_out_of_routing_at_once_and_shows_the_window_once(self) -> None:
            a = self.mk("g1", "degraded_fallback", state="ready")
            shown: List[str] = []
            self.acc.show_hook = lambda acct: shown.append(acct["id"])
            self.assertTrue(self.acc.needs_human("g1", {"kind": "captcha", "reason": "a CAPTCHA is shown", "signal": "captcha"}))
            self.assertEqual(a["lifecycle"]["state"], "needs_human")
            self.assertEqual((a["human"]["kind"], a["human"]["prev_state"]), ("captcha", "degraded_fallback"))
            self.assertIn("never solves", a["lifecycle"]["reason"])
            self.assertEqual(shown, ["g1"])
            self.assertTrue(self.acc.needs_human("g1", {"kind": "captcha", "reason": "again"}))
            self.assertEqual(shown, ["g1"])                                          # the window is not opened twice
            r = self.app.engine.assess("acct:g1", {"name": "t", "kind": "auto"}, {"capabilities": [], "tokens": 0, "max_tokens": 0}, "", set(), default_routing(), None)
            self.assertIn("needs_human", [c for c, _d in r["codes"]])
            self.assertEqual(json.loads(self.store.path("accounts.json").read_text())[0]["lifecycle"]["state"], "needs_human")
            d = self.mk("d1", "disabled", state="ready")
            self.assertFalse(self.acc.needs_human("d1", {"kind": "captcha"}))
            self.assertEqual(d["lifecycle"]["state"], "disabled")
            self.assertIn("a1" if False else "human", [x for x in self.acc.public() if x["id"] == "g1"][0])

        def test_o7_after_the_owner_solves_it_the_session_is_rechecked_and_the_account_goes_back_to_a_safe_state(self) -> None:
            calls: List[str] = []
            def good(a: Dict[str, Any], s_: Dict[str, Any], r_: Any) -> Dict[str, Any]:
                calls.append("good")
                return {"result": "ok", "confidence": "high"}
            def bad(a: Dict[str, Any], s_: Dict[str, Any], r_: Any) -> Dict[str, Any]:
                calls.append("bad")
                return {"result": "rejected", "confidence": "high"}
            self.acc.show_hook = lambda acct: None
            a = self.mk("g1", "stable_direct", state="ready")
            self.sess("g1")
            with self.assertRaises(BridgeError) as cm:
                self.acc.human_done("g1")
            self.assertEqual(cm.exception.status, 409)
            self.acc.needs_human("g1", {"kind": "bot_check", "reason": "x"})
            out = self.acc.human_done("g1", probe=good)
            self.assertEqual(out["state"], "degraded_fallback")                       # never straight back to stable_direct: that needs O8
            self.assertEqual(out["validity"]["status"], "valid")
            self.assertNotIn("human", a)
            self.acc.needs_human("g1", {"kind": "captcha", "reason": "y"})
            out = self.acc.human_done("g1", probe=bad)
            self.assertEqual(out["state"], "needs_login")
            self.assertEqual(a["state"], "login_required")
            self.assertEqual(calls, ["good", "bad"])
            b = self.mk("g2", "logging_in", state="learning")                          # a check in the middle of a login: the login window is already open
            self.acc.needs_human("g2", {"kind": "captcha", "reason": "z"}, show=True)
            self.assertEqual(b["human"]["window"], "open")
            self.assertEqual(self.acc.human_done("g2", probe=lambda *x: calls.append("never") or {})["state"], "logging_in")
            self.assertNotIn("never", calls)

        def test_o7_a_challenge_page_answer_goes_to_the_human_not_to_an_automatic_relearn(self) -> None:
            a = self.mk("g1", "degraded_fallback", state="ready")
            self.acc.show_hook = lambda acct: None
            self.cfg.data["profile_auto_relearn"] = True
            self.acc.auto_relearn = lambda *x, **k: self.fail("a challenge must not start an automatic re-learn")
            self.acc.note_signals(a, BridgeError("empty answer from site: <html>Just a moment...</html>", "empty", 502))
            self.assertEqual(a["lifecycle"]["state"], "needs_human")
            self.assertEqual(a["human"]["kind"], "bot_check")

