        # ---------------------------------------------------------------- O10
        def test_o10_manifest_is_written_holds_no_secret_and_has_a_fingerprint_per_account(self) -> None:
            self.mk("g1")
            self.sess("g1", secret="TOPSECRETCOOKIE-999")
            self.acc.save()
            m = load_manifest(self.store)
