    class TestReportInSync(unittest.TestCase):
        """7.35 (owner rule): the hand-off report must match the code and the ledger. Skipped only when the report file is not next to bridge.py."""

        def setUp(self) -> None:
            here = Path(__file__).resolve()
            self.rep = here.with_name("HANDOFF_REPORT.md")
            if not self.rep.exists():
                self.skipTest("HANDOFF_REPORT.md is not next to bridge.py")
            self.s = self.rep.read_text(encoding="utf-8")
            self.code = here.read_bytes()

        def test_report_version_and_hash_are_those_of_this_file(self) -> None:
            m = re.search(r"Current version (\S+?), SHA-256 starts with `([0-9a-f]{12})`", self.s)
            self.assertIsNotNone(m, "section 0 must state the current version and the hash prefix")
            self.assertEqual(m.group(1), VERSION)
            self.assertEqual(m.group(2), hashlib.sha256(self.code).hexdigest()[:12], "the hash in section 0 is not the hash of this bridge.py")
            self.assertIn(f"`bridge.py` SHA-256 starts with `{m.group(2)}`", self.s, "0A base version must carry the same hash")

        def test_report_has_the_mandatory_per_turn_parts_for_this_version(self) -> None:
            self.assertIn("OWNER-MANDATORY EVERY TURN", self.s)
            self.assertRegex(self.s, r"(?m)^\| " + re.escape(VERSION) + r"(?: [^|]*)? \|", "0D needs a row for this version")
            self.assertRegex(self.s, r"(?m)^- " + re.escape(VERSION) + r" \|", "the DEFERRED LOG needs a line for this version")
            self.assertRegex(self.s, r"(?m)^- \*\*Step \(next, \d+\.\d+", "0A needs a next step with its version")

        def test_0d_status_table_equals_the_ledger_counts(self) -> None:
            a, b = re.search(r"(?m)^## 2\. LEDGER", self.s), re.search(r"(?m)^## 3\. DECISIONS", self.s)
            cnt: Dict[str, int] = {}
            for line in self.s[a.start():b.start()].splitlines():
                m = re.match(r"\|\s*[A-Z]+\d+\s*\|[^|]*\|\s*(DONE|PARTIAL|TODO|BLOCKED)\s*\|", line)
                if m:
                    cnt[m.group(1)] = cnt.get(m.group(1), 0) + 1
            sec = self.s[self.s.index("### Status in one table"):]
            sec = sec[:sec.index("\n\n###")] if "\n\n###" in sec else sec[:1500]
            shown = {k: int(v) for k, v in re.findall(r"(?m)^\| (DONE|PARTIAL|TODO) \| (\d+) \|", sec)}
            for k in ("DONE", "PARTIAL", "TODO"):
                self.assertEqual(shown.get(k), cnt.get(k, 0), f"0D status table disagrees with the ledger for {k}: recompute it with the 0B script")

        def test_ledger_names_only_tests_that_exist(self) -> None:
            names = set(re.findall(r"def (test_\w+)", self.code.decode("utf-8")))
            a, b = re.search(r"(?m)^## 2\. LEDGER", self.s), re.search(r"(?m)^## 3\. DECISIONS", self.s)
            missing = [t for t in set(re.findall(r"test_\w+", self.s[a.start():b.start()])) if t not in names and not (t.endswith("_") and any(n.startswith(t) for n in names))]
            self.assertEqual(missing, [], "the ledger cites tests that do not exist")

    class TestGroupO26(unittest.TestCase):
        """7.35 O26: the investigation loop on a mock site, mock scripts and a FAKE brain (no real model, site or browser)."""
        CANARY = "CANARY-SECRET-77aa88bb99cc"

        def setUp(self) -> None:
            self.h = TestGroupO17("test_o17_hmac_header_plus_pow_is_direct_candidate_after_the_cross_check")
            self.exs = self.h.site(sig=True, pow_=False)
            self.scripts = self.h.scripts()
            self.sha = o17_script_hash(self.h.APP)
            self.spent: List[Tuple[int, str]] = []

        def brain(self, answers: Dict[str, Any], budget: Optional[int] = None, secrets_: Optional[List[str]] = None) -> Tuple["Brain", "FakeBrain"]:
            fake = FakeBrain(answers)

            def sp(n: int, w: str) -> None:
                if budget is not None and sum(x for x, _ in self.spent) + n > budget:
                    raise BridgeError("learning budget used up", "client", 429)
                self.spent.append((n, w))
            return Brain(fake.send, sp, secrets_, site="mock17.test"), fake

        def go(self, br: "Brain", **kw: Any) -> Dict[str, Any]:
            kw.setdefault("secrets_", None)
            return o26_investigate(br, self.exs, self.scripts, self.h.HOST, "POST /api/chat", ("body.$.prompt",), **kw)

        def act(self, action: str, **params: Any) -> Dict[str, Any]:
            return {"action": action, "params": params, "reason": "r"}

        def view_script(self) -> Dict[str, Any]:
            return self.act("view_script", sha256=self.sha, lines=[1, 7])

        def good_spec(self) -> Dict[str, Any]:
            sp = self.h.sig_spec()
            return self.act("spec", **{k: sp[k] for k in ("loc", "name", "provenance", "expr")})

        def test_o26_a_custom_header_is_solved_from_the_served_script_and_the_deterministic_gates_agree(self) -> None:
            br, fake = self.brain({"o26_round": [self.view_script(), self.act("hypothesis", part="header.x-sig", claim="hmac of ts and prompt", evidence_quotes=["hmacSha256(SECRET, ts"]), self.good_spec()]})
            r = self.go(br)
            self.assertEqual(r["outcome"], "spec", r)
            self.assertEqual((r["requests"], r["rounds"], [x["loc"] for x in r["specs"]]), (3, 3, ["header.x-sig"]))
            self.assertEqual(r["specs"][0]["provenance"]["by"], "o26-loop")
            again = o17_analyze(self.exs, self.h.HOST, self.scripts, r["specs"], "POST /api/chat", ("body.$.prompt",))
            self.assertEqual(again["verdict"], "direct_candidate")                                    # the same deterministic gates accept it independently of the loop
            self.assertEqual(r["hypotheses"][0]["status"], "quoted")
            self.assertNotIn("direct_candidate stable", json.dumps(r))                                # nothing is promoted by the loop

        def test_o26_a_wrong_hypothesis_is_refuted_by_an_experiment_and_a_wrong_spec_by_the_cross_check(self) -> None:
            ran: List[Tuple[str, Dict[str, Any]]] = []

            def exp(kind: str, params: Dict[str, Any]) -> Dict[str, Any]:
                ran.append((kind, params))
                return {"accepted": True}
            wrong = self.act("spec", loc="header.x-sig", name="s", provenance=self.h.prov([2, 5]), expr={"sha256": {"ref": "body.$.prompt"}, "enc": "hex"})
            br, _ = self.brain({"o26_round": [self.view_script(), self.act("hypothesis", part="header.x-sig", claim="static value", evidence_quotes=["function sign(ts, prompt)"]),
                                              self.act("experiment", kind="omit_header", loc="header.x-sig"), wrong, self.good_spec()]})
            r = self.go(br, experiment=exp)
            self.assertEqual(r["outcome"], "spec", r)
            self.assertEqual(len(ran), 1)
            self.assertEqual(len(r["refuted"]), 2)
            self.assertIn("accepted the request without it", r["refuted"][0])
            self.assertIn("not trusted", r["refuted"][1])
            self.assertEqual(r["hypotheses"][0]["status"], "refuted")
            self.assertEqual(len(r["specs"]), 1)
            self.assertIn("hmac_sha256", json.dumps(r["specs"][0]["expr"]))                          # only the checked spec was kept
            self.assertEqual(sum(n for n, w in self.spent if w == "o26 experiment"), 1)                # the experiment was counted in the budget

        def test_o26_a_fabricated_quote_and_a_spec_for_lines_never_shown_are_refused(self) -> None:
            br, _ = self.brain({"o26_round": [self.act("hypothesis", part="header.x-sig", claim="c", evidence_quotes=["totally invented source text"]), self.good_spec()]})
            r = self.go(br, max_rounds=2)
            self.assertEqual(r["outcome"], "exhausted")
            self.assertEqual(r["specs"], [])
            self.assertIn("not literally in anything you were shown", r["refuted"][0])
            self.assertIn("never shown", r["refuted"][1])
            self.assertEqual(r["hypotheses"], [])

        def test_o26_a_captcha_style_token_ends_in_needs_human_without_asking_the_brain_anything(self) -> None:
            self.exs = self.h.site(sig=False, pow_=False, extra=lambda k: [("cf-turnstile-token", f"0.tok{k}Zx9QwLm")])
            br, fake = self.brain({"o26_round": [self.view_script()]})
            r = self.go(br)
            self.assertEqual((r["outcome"], r["requests"], fake.prompts, r["specs"]), ("needs_human", 0, [], []))

        def test_o26_a_brain_that_answers_nonsense_changes_nothing_and_ends_in_an_honest_give_up(self) -> None:
            br, fake = self.brain({})
            r = self.go(br)
            self.assertEqual((r["outcome"], r["specs"]), ("give_up", []))
            self.assertIn("no usable answer", r["reason"])
            self.assertEqual(r["requests"], 4)                                                        # two rounds, each one question plus one reformat; then it stops
            br2, _ = self.brain({"o26_round": [self.act("delete_everything"), self.act("give_up", reason="not reproducible")]})
            r2 = self.go(br2)
            self.assertEqual((r2["outcome"], r2["reason"], r2["specs"]), ("give_up", "not reproducible", []))
            self.assertIn("not an allowed action", r2["refuted"][0])

        def test_o26_a_budget_of_zero_sends_nothing_and_the_outcome_says_budget(self) -> None:
            br, fake = self.brain({"o26_round": [self.view_script()]}, budget=0)
            r = self.go(br)
            self.assertEqual((r["outcome"], fake.prompts, r["requests"]), ("budget", [], 0))
            br2, _ = self.brain({"o26_round": [self.view_script(), self.act("experiment", kind="omit_header", loc="header.x-sig")]}, budget=2)
            r2 = self.go(br2, experiment=lambda k, p: {"accepted": False})
            self.assertEqual(r2["outcome"], "budget")                                                 # the experiment would have been the 3rd counted request

        def test_o26_rounds_are_bounded_and_experiments_are_refused_when_none_is_configured(self) -> None:
            br, _ = self.brain({"o26_round": [self.act("experiment", kind="omit_header", loc="header.x-sig")]})
            r = self.go(br, max_rounds=3)
            self.assertEqual((r["outcome"], r["rounds"], r["requests"]), ("exhausted", 3, 3))
            self.assertIn("no experiment is available", r["refuted"][0])
            bad_loc = self.brain({"o26_round": [self.act("experiment", kind="omit_header", loc="header.not-there")]})[0]
            self.assertIn("a part of this endpoint", self.go(bad_loc, max_rounds=1, experiment=lambda k, p: {"accepted": True})["refuted"][0])

        def test_o26_a_stored_credential_in_a_capture_is_redacted_before_the_brain_sees_it(self) -> None:
            self.exs = self.h.site(sig=True, pow_=False, extra=lambda k: [("x-extra", self.CANARY)])
            br, fake = self.brain({"o26_round": [self.act("view_capture", id="c1", loc="header.x-extra"), self.act("give_up", reason="stop")]}, secrets_=[self.CANARY])
            r = self.go(br, secrets_=[self.CANARY])
            self.assertEqual(r["outcome"], "give_up")
            self.assertEqual(len(fake.prompts), 2)
            self.assertFalse(any(self.CANARY in p for p in fake.prompts))
            self.assertNotIn(self.CANARY, json.dumps(r))

        def test_o26_log_and_results_hold_no_evidence_text_and_the_loop_code_names_no_site_or_provider(self) -> None:
            br, _ = self.brain({"o26_round": [self.view_script(), self.act("give_up", reason="x")]})
            r = self.go(br)
            self.assertNotIn("hmacSha256", json.dumps(r["log"]))
            src = Path(__file__).read_text(encoding="utf-8")
            body = src[src.index("O26_ACTION_SET ="):src.index("# --- end of the O26 loop ---")].lower()
            for name in ("chatgpt", "openai", "gemini", "claude", "anthropic", "deepseek", "kimi", "qwen", "grok", "perplexity", "mistral", "copilot", "poe.com"):
                self.assertNotIn(name, body)

    class TestGroupO27(unittest.TestCase):
        """7.36 O27: brain-authored tokens.py with the gates, on the O17 mock site and a FAKE brain (no real model, site or browser)."""

        def setUp(self) -> None:
            self.h = TestGroupO17("test_o17_hmac_header_plus_pow_is_direct_candidate_after_the_cross_check")
            self.exs = self.h.site(sig=True, pow_=False)
            self.scripts = self.h.scripts()
            self.sha12 = o17_script_hash(self.h.APP)[:12]
            sp = self.h.sig_spec()
            sp["provenance"] = dict(sp["provenance"], by="o26-loop")
            self.o26 = {"outcome": "spec", "specs": [sp], "reason": ""}
            self.spent: List[Tuple[int, str]] = []
            self.tmp: Optional[Path] = None

        def tearDown(self) -> None:
            if self.tmp:
                shutil.rmtree(self.tmp, ignore_errors=True)

        def good(self, key: str = "mock-signing-key-91", extra: str = "") -> str:
            return ('"""Signature token of the mock site, ported from its client script."""\nimport hashlib\nimport hmac\n\n'
                    f'# source: {self.sha12} lines 2-2\nSIGNING_KEY = "{key}"\n\n\n'
                    f'# source: {self.sha12} lines 2-5\ndef make_header_x_sig(ctx: dict[str, str]) -> str:\n'
                    '    """Return the hex HMAC-SHA256 of the timestamp and the prompt, signed with the site key."""\n'
                    '    message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"]\n'
                    '    return hmac.new(SIGNING_KEY.encode("utf-8"), message.encode("utf-8"), hashlib.sha256).hexdigest()\n'
                    + extra + '\n\nTOKENS = {"header.x-sig": make_header_x_sig}\n')

        def brain(self, answers: Dict[str, Any], budget: Optional[int] = None) -> Tuple["Brain", "FakeBrain"]:
            fake = FakeBrain(answers)

            def sp(n: int, w: str) -> None:
                if budget is not None and sum(x for x, _ in self.spent) + n > budget:
                    raise BridgeError("learning budget used up", "client", 429)
                self.spent.append((n, w))
            return Brain(fake.send, sp, None, site="mock17.test"), fake

        def go(self, br: "Brain", o26: Optional[Dict[str, Any]] = None, **kw: Any) -> Dict[str, Any]:
            return o27_author(br, self.o26 if o26 is None else o26, self.exs, self.scripts, self.h.HOST, "POST /api/chat", ("body.$.prompt",), **kw)

        def rules(self, r: Dict[str, Any], draft: int = -1) -> set:
            return {x for g in r["gate_log"][draft]["gates"] for x in g["rules"]}

        def test_o27_a_correct_draft_passes_every_gate_and_the_generated_test_file_runs_for_real(self) -> None:
            br, fake = self.brain({"o27_author": {"tokens_py": self.good()}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "modules", r)
            self.assertEqual((r["requests"], r["drafts"]), (1, 1))
            self.assertEqual([(g["gate"], g["ok"]) for g in r["gate_log"][0]["gates"]], [("ast", True), ("interface", True), ("provenance", True), ("quality", True), ("replay", True), ("differential", True), ("generated_tests", True)])
            self.assertEqual(r["files"]["tokens.py"], self.good())
            self.assertIn("protocol.py", r["files"])                                                  # data files stay deterministic (o18_translate)
            self.tmp = Path(tempfile.mkdtemp())
            (self.tmp / "tokens.py").write_text(r["files"]["tokens.py"], encoding="utf-8")
            (self.tmp / "test_tokens.py").write_text(r["test_file"], encoding="utf-8")
            p = subprocess.run([sys.executable, "-m", "unittest", "test_tokens"], cwd=str(self.tmp), capture_output=True, text=True, timeout=60)
            self.assertEqual(p.returncode, 0, p.stderr[-400:])
            self.assertTrue(all(ord(c) < 128 for c in r["test_file"]))

        def test_o27_a_hidden_import_is_refused_and_nothing_is_written_or_promoted(self) -> None:
            bad = self.good().replace("import hmac\n", "import hmac\nimport os\n")
            br, _ = self.brain({"o27_author": {"tokens_py": bad}, "o27_fix": {"tokens_py": bad}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "refused")
            self.assertEqual((r["files"], r["drafts"], r["requests"]), ({}, 1, 2))                    # the same draft again = no progress = no more spend
            self.assertEqual(self.rules(r), {"ast-allow-list"})
            self.assertEqual([g["gate"] for g in r["gate_log"][0]["gates"]], ["ast"])               # nothing after the allow-list ran on that text
            self.tmp, store, _, _ = mk_env()
            self.assertEqual(o27_commit(store, self.h.HOST, r, self.scripts, self.o26["specs"], "POST /api/chat")["written"], "draft_only")
            hd = safe_host_dir(self.h.HOST)
            self.assertIsNone(store.read(f"site_modules/{hd}/manifest.json", None))                    # the live set is untouched
            self.assertIn("import os", store.read(f"site_modules/{hd}/drafts/o27/draft.json", None)["tokens_py"])
            self.assertFalse(o18_load(store, self.h.HOST)["use"])

        def test_o27_a_messy_but_correct_draft_is_refused_with_rule_names_and_passes_after_the_fix_round(self) -> None:
            body = "\n".join(f"    note_{i} = 1" for i in range(45))
            messy = ('"""Messy."""\nimport hashlib\nimport hmac\n\n'
                     f'# source: {self.sha12} lines 2-5\ndef make_header_x_sig(ctx):\n    k = "mock-signing-key-91"\n    stamp = ctx.get("header.x-ts", "0")\n    limit = 5\n{body}\n'
                     '    return hmac.new(k.encode("utf-8"), (stamp + "." + ctx["body.$.prompt"]).encode("utf-8"), hashlib.sha256).hexdigest()\n\nTOKENS = {"header.x-sig": make_header_x_sig}\n')
            br, fake = self.brain({"o27_author": {"tokens_py": messy}, "o27_fix": {"tokens_py": self.good()}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "modules", r)
            self.assertEqual((r["drafts"], r["requests"]), (2, 2))
            first = self.rules(r, 0)
            for rule in ("function-too-long", "missing-docstring", "missing-type-hint", "magic-string", "magic-number", "silent-default", "short-name", "dead-code"):
                self.assertIn(rule, first)
            self.assertNotIn("replay", [g["gate"] for g in r["gate_log"][0]["gates"]])                  # the correct output is not enough while static rules fail
            self.assertIn("function-too-long", fake.prompts[-1])                                       # the fix request names the rules
            self.assertIn("missing-docstring", fake.prompts[-1])

        def test_o27_provenance_a_constant_not_in_the_cited_lines_a_missing_comment_and_an_unknown_script_are_refused(self) -> None:
            for text, rule in ((self.good(key="not-in-the-script-1"), "literal-not-in-source"),
                               (self.good().replace(f"# source: {self.sha12} lines 2-5\n", ""), "missing-provenance"),
                               (self.good().replace(f"# source: {self.sha12} lines 2-2", "# source: 000000000000 lines 2-2"), "provenance-unverifiable"),
                               (self.good().replace(f"lines 2-5", "lines 1-7"), "provenance-mismatch")):
                br, _ = self.brain({"o27_author": {"tokens_py": text}})
                r = self.go(br)
                self.assertEqual(r["outcome"], "refused", rule)
                self.assertIn(rule, self.rules(r), rule)

        def test_o27_a_recorded_output_cannot_be_smuggled_in_as_a_capture_constant(self) -> None:
            sig = dict(request_locations(self.exs[1]))["header.x-sig"]
            old = f'# source: {self.sha12} lines 2-2\nSIGNING_KEY = "mock-signing-key-91"'
            cheat = self.good().replace(old, f'# capture: {self.exs[1]["id"]}\nSIGNING_KEY = "{sig}"')
            br, _ = self.brain({"o27_author": {"tokens_py": cheat}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "refused")
            self.assertIn("literal-not-in-source", self.rules(r))

        def test_o27_a_wrong_algorithm_fails_the_replay_gate_and_is_fixed_in_the_next_round(self) -> None:
            wrong = self.good().replace('return hmac.new(SIGNING_KEY.encode("utf-8"), message.encode("utf-8"), hashlib.sha256).hexdigest()',
                                        'return hashlib.sha256((SIGNING_KEY + message).encode("utf-8")).hexdigest()').replace("import hmac\n", "")
            br, _ = self.brain({"o27_author": {"tokens_py": wrong}, "o27_fix": {"tokens_py": self.good()}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "modules", r)
            g0 = {g["gate"]: g["ok"] for g in r["gate_log"][0]["gates"]}
            self.assertEqual((g0["quality"], g0["replay"]), (True, False))
            self.assertNotIn("differential", g0)                                                       # replay failed: the later gates did not run on it

        def test_o27_a_draft_that_matches_every_capture_but_does_not_compute_the_value_is_caught_by_the_differential_gate(self) -> None:
            cut = self.good().replace('message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"]', 'message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"].split("~")[0]')
            br, _ = self.brain({"o27_author": {"tokens_py": cut}})
            r = self.go(br)
            self.assertEqual(r["outcome"], "refused")
            g = {x["gate"]: x["ok"] for x in r["gate_log"][0]["gates"]}
            self.assertEqual((g["replay"], g["differential"]), (True, False))                          # identical on the recorded captures, different on new inputs

        def test_o27_nothing_is_asked_without_an_accepted_spec_and_a_nonsense_brain_or_empty_budget_changes_nothing(self) -> None:
            br, fake = self.brain({})
            r = self.go(br, {"outcome": "give_up", "specs": []})
            self.assertEqual((r["outcome"], r["requests"], fake.prompts), ("nothing_to_author", 0, []))
            br, _ = self.brain({"o27_author": "I cannot do this."})
            r = self.go(br)
            self.assertEqual((r["outcome"], r["files"], r["drafts"]), ("brain_unusable", {}, 0))
            br, fake = self.brain({"o27_author": {"tokens_py": self.good()}}, budget=0)
            r = self.go(br)
            self.assertEqual((r["outcome"], fake.prompts), ("budget", []))

        def test_o27_three_fix_rounds_at_most_then_an_honest_refusal_that_stores_only_the_draft(self) -> None:
            bad = [self.good().replace("import hmac\n", "import hmac\nimport os\n" + "# attempt %d\n" % k) for k in range(4)]
            br, _ = self.brain({"o27_author": {"tokens_py": bad[0]}, "o27_fix": [{"tokens_py": b} for b in bad[1:]]})
            r = self.go(br)
            self.assertEqual((r["outcome"], r["drafts"], r["requests"], r["files"]), ("refused", 4, 4, {}))
            self.assertIn("ast-allow-list", r["reason"])
            self.spent.clear()
            br, _ = self.brain({"o27_author": {"tokens_py": bad[0]}, "o27_fix": [{"tokens_py": b} for b in bad[1:]]}, budget=2)
            r = self.go(br)
            self.assertEqual((r["outcome"], r["drafts"], r["requests"]), ("budget", 2, 2))             # the brain budget bounds the fix rounds too

        def test_o27_a_modules_result_is_committed_through_o18_write_and_loads_at_runtime(self) -> None:
            br, _ = self.brain({"o27_author": {"tokens_py": self.good()}})
            r = self.go(br)
            self.tmp, store, _, _ = mk_env()
            w = o27_commit(store, self.h.HOST, r, self.scripts, self.o26["specs"], "POST /api/chat", {"outcome": "reviewed", "verdict": "v", "findings": [], "confirmed_defects": 0, "requests": 1})
            self.assertEqual(w["written"], "modules")
            hd = safe_host_dir(self.h.HOST)
            self.assertTrue(store.path("site_modules", hd, "test_tokens.py").is_file())
            self.assertEqual(store.read(f"site_modules/{hd}/review.json", None)["outcome"], "reviewed")
            self.assertNotIn("test_tokens.py", w["manifest"]["modules"])                               # the test file is not part of the runtime set
            ld = o18_load(store, self.h.HOST, self.scripts)
            self.assertTrue(ld["use"], ld)
            ctx = dict(request_locations(self.exs[1]))
            self.assertEqual(ld["tokens"]["header.x-sig"]({k: v for k, v in ctx.items() if k != "header.x-sig"}), ctx["header.x-sig"])

        def test_o27_commit_preserves_compatible_native_data_for_the_o8_battery(self) -> None:
            br, _ = self.brain({"o27_author": {"tokens_py": self.good()}})
            result = self.go(br)
            self.tmp, store, _, _ = mk_env()
            native = {"stream": {"format": "sse", "text_paths": ["$.choices.0.delta.content"]},
                      "prompt_loc": "body.$.prompt", "conv_loc": "", "conv_path": ""}
            seeded = o18_run(store, self.h.HOST, self.exs, self.scripts, [self.o26["specs"][0]],
                             ("body.$.prompt",), "POST /api/chat", native=native)
            self.assertTrue(seeded["ok"], seeded)
            self.assertTrue(o18_load(store, self.h.HOST, self.scripts).get("native"))
            saved = o27_commit(store, self.h.HOST, result, self.scripts, self.o26["specs"], "POST /api/chat")
            self.assertEqual(saved["written"], "modules")
            loaded = o18_load(store, self.h.HOST, self.scripts)
