        def test_o27_quality_rules_each_have_a_stable_name(self) -> None:
            cases = {
                "bare-except": 'def run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    try:\n        return ctx["a"]\n    except:\n        raise ValueError("x")\n',
                "silent-default": 'def run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    try:\n        return ctx["a"]\n    except KeyError:\n        return ""\n',
                "unused-import": 'import json\n\n\ndef run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    return ctx["a"]\n',
                "global-mutable-state": 'CACHE = {}\n\n\ndef run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    return ctx["a"]\n',
                "too-many-parameters": 'def run_it(one: str, two: str, three: str, four: str, five: str, six: str) -> str:\n    """Doc."""\n    return one\n',
                "docstring-not-one-line": 'def run_it(ctx: dict[str, str]) -> str:\n    """Doc.\n\n    More.\n    """\n    return ctx["a"]\n',
                "nondeterministic-source": 'import time\n\n\ndef run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    return str(time.time())\n',
                "dead-code": 'def run_it(ctx: dict[str, str]) -> str:\n    """Doc."""\n    return ctx["a"]\n    return ctx["b"]\n',
                "module-level-code": 'print_value = len("abc")\nfor item in range(3):\n    pass\n',
            }
            for rule, src in cases.items():
                got = {p["rule"] for p in o27_quality_problems('"""Module."""\n' + src, ("a", "b"))}
                self.assertIn(rule, got, (rule, got))
            clean = o27_quality_problems(self.good(), ("header.x-ts", "body.$.prompt"))
            self.assertEqual(clean, [])

        def test_o27_proof_of_work_cases_and_the_reference_module_pass_the_pow_paths_of_the_gates(self) -> None:
            exs = self.h.site(sig=True, pow_=True)
