            cases = o27_cases(used, exs, "POST /api/chat")
            pw = [c for c in cases if c["loc"] == "header.x-pow"]
            self.assertEqual((len(pw), pw[0]["pow"]["bits"], pw[0]["expect"]), (3, 2, None))
            self.assertEqual(o27_run_cases(ref, cases), [])
            self.assertEqual(o27_differential(ref, ref, used, cases), [])
            compile(o27_test_text(self.h.HOST, cases), "test_tokens.py", "exec")

