    class TestGroupO28(unittest.TestCase):
        """7.36 O28: the advisory review on the O27 result of the O17 mock site and a FAKE reviewer (no real model)."""

        def setUp(self) -> None:
            self.h27 = TestGroupO27("test_o27_a_correct_draft_passes_every_gate_and_the_generated_test_file_runs_for_real")
            self.h27.setUp()
            self.spec = self.h27.o26["specs"][0]
            self.subtle = self.h27.good().replace('message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"]', 'message = ctx["header.x-ts"] + "." + ctx["body.$.prompt"].replace("\\n", " ")')
            br, _ = self.h27.brain({"o27_author": {"tokens_py": self.subtle}})
            self.r27 = self.h27.go(br)

        def tearDown(self) -> None:
            self.h27.tearDown()

        def review(self, answer: Any, o27: Optional[Dict[str, Any]] = None, budget: Optional[int] = None) -> Tuple[Dict[str, Any], "FakeBrain"]:
            self.h27.spent.clear()
            br, fake = self.h27.brain({"o28_review": answer}, budget=budget)
            return o28_review(br, self.r27 if o27 is None else o27, self.h27.scripts, [self.spec], self.h27.h.HOST), fake

        def test_o28_a_subtle_difference_that_passes_every_recorded_capture_is_flagged_and_confirmed_by_one_extra_run(self) -> None:
            self.assertEqual(self.r27["outcome"], "modules", self.r27)                                  # the gates really accepted this draft: the review is the second line
            probe = {"loc": "header.x-sig", "ctx": {"header.x-ts": "1900000001000", "body.$.prompt": "line1\nline2"}}
            ans = {"verdict": "one input class is handled differently from the script", "findings": [
                {"check": "matches_source", "severity": "defect", "text": "newlines in the prompt are replaced; the cited lines do not do that", "quote": '.replace("\\n", " ")', "probe": probe},
                {"check": "readability", "severity": "info", "text": "fine"}]}
            r, fake = self.review(ans)
            self.assertEqual((r["outcome"], r["requests"], r["promotes"], r["confirmed_defects"]), ("reviewed", 1, False, 1), r)
            self.assertEqual((r["findings"][0]["probe"], r["findings"][0]["quote_ok"]), ("confirmed", True))
            self.assertTrue(any("probe confirmed" in x for x in o28_report_lines(r)))
            self.assertIn("matches_source", fake.prompts[0])                                           # the fixed checklist was sent

        def test_o28_an_opinion_without_a_reproducing_probe_is_never_a_confirmed_defect_and_a_fabricated_quote_is_marked(self) -> None:
            same = {"loc": "header.x-sig", "ctx": {"header.x-ts": "1900000001000", "body.$.prompt": "plain text"}}
            ans = {"verdict": "v", "findings": [
                {"check": "edge_cases", "severity": "defect", "text": "might differ", "quote": "this text is not in the module at all", "probe": same},
                {"check": "nothing_guessed", "severity": "warn", "text": "opinion only"},
                {"check": "not_a_check", "severity": "defect", "text": "dropped"},
                {"check": "edge_cases", "severity": "defect", "text": "bad probe", "probe": {"loc": "header.x-sig", "ctx": {}}}]}
            r, _ = self.review(ans)
            self.assertEqual((r["confirmed_defects"], [f["probe"] for f in r["findings"]]), (0, ["not_reproduced", None, "invalid"]))
            self.assertIs(r["findings"][0]["quote_ok"], False)
            self.assertTrue(any("quote not found" in x for x in o28_report_lines(r)))

        def test_o28_only_a_gated_module_set_is_reviewed_and_a_failed_or_empty_budget_review_changes_nothing(self) -> None:
            r, fake = self.review({"verdict": "v", "findings": []}, o27={"outcome": "refused", "files": {}})
            self.assertEqual((r["outcome"], r["requests"], fake.prompts), ("skipped", 0, []))
            r, _ = self.review("not json at all")
            self.assertEqual((r["outcome"], r["findings"], r["promotes"]), ("failed", [], False))
            r, fake = self.review({"verdict": "v", "findings": []}, budget=0)
            self.assertEqual((r["outcome"], fake.prompts), ("failed", []))
