    class TestLogFile(unittest.TestCase):
        """7.28: the persistent log file (`logs/bridge.log`): lines with a full date, rotation, secrets masked, thread exceptions with traceback, lifecycle transitions."""

        def setUp(self) -> None:
            self.tmp = Path(tempfile.mkdtemp(prefix="bridge-log-"))
            self.old = dict(_LOGFILE)

        def tearDown(self) -> None:
            _LOGFILE.clear()
            _LOGFILE.update(self.old)
            sys.excepthook, threading.excepthook = sys.__excepthook__, threading.__excepthook__
            shutil.rmtree(self.tmp, ignore_errors=True)

        def test_lines_reach_the_file_with_date_and_secrets_masked(self) -> None:
            p = log_file_open(self.tmp / "logs")
            log("hello world", "warn")
            log("token Bearer abcdefghijklmnop1234567890 leaked", "error")
            txt = p.read_text("utf-8")
            self.assertRegex(txt, r"\d{4}-\d\d-\d\d \d\d:\d\d:\d\d WARN  hello world")
            self.assertIn("ERROR", txt)
            self.assertNotIn("abcdefghijklmnop1234567890", txt)

        def test_rotation_keeps_a_bounded_number_of_files(self) -> None:
            p = log_file_open(self.tmp / "logs", max_bytes=300, keep=2)
            for i in range(60):
                log(f"line {i} " + "x" * 40)
            names = sorted(x.name for x in p.parent.iterdir())
            self.assertEqual(names, ["bridge.log", "bridge.log.1", "bridge.log.2"])

        def test_an_unwritable_folder_never_raises(self) -> None:
            blocker = self.tmp / "file"
            blocker.write_text("x")
            self.assertIsNone(log_file_open(blocker / "sub"))
            log("still fine")                                                                # no exception, console and memory buffer still work

