    class TestPersonalChrome(unittest.TestCase):
        """7.24: the personal-Chrome layer. A FAKE extension (Python) speaks the real wire protocol to a real hub, and the real background.js runs under node with a stubbed
        `chrome` API against the same hub. NOT covered here (needs a real Chrome): the DOM finder script, real debugger events, real tab behaviour."""
        ORIGIN = "chrome-extension://abcdefghijklmnopabcdefghijklmnop"

        def setUp(self) -> None:
            self.tmp = Path(tempfile.mkdtemp(prefix="bridge_pc_"))
            s = socket.socket()
            s.bind(("127.0.0.1", 0))
            self.port = s.getsockname()[1]
            s.close()
            self.hub = PCHub(self.tmp / "personal_chrome", self.port)
            self.hub.grace = 1.5
            self.assertTrue(self.hub.start())
            self.exts: List[Any] = []

        def tearDown(self) -> None:
            for e in self.exts:
                e.stop()
            self.hub.stop()
            shutil.rmtree(self.tmp, ignore_errors=True)

        # -- helpers -----------------------------------------------------------------------------------------------------------------------------
        def post(self, path: str, body: Any = None, origin: Optional[str] = None, token: str = "", host: Optional[str] = None, raw: Optional[bytes] = None) -> Tuple[int, Any]:
            c = hc.HTTPConnection("127.0.0.1", self.port, timeout=15)
            h = {"Content-Type": "application/json", "Host": host or f"127.0.0.1:{self.port}"}
            if origin:
                h["Origin"] = origin
            if token:
                h["X-Bridge-PC-Token"] = token
            c.request("POST", path, body=raw if raw is not None else json.dumps(body or {}).encode(), headers=h)
            r = c.getresponse()
            data = r.read()
            c.close()
            try:
                return r.status, json.loads(data)
            except Exception:
                return r.status, data

        def pair(self, client_id: str = "legacy", client_name: str = "Chrome profile") -> str:
            code = self.hub.new_pairing()
            st, j = self.post("/pc/pair", {"code": code, "client_id": client_id, "client_name": client_name}, origin=self.ORIGIN)
            self.assertEqual(st, 200)
            return j["token"]

        def fake(self, tabs: Optional[Dict[int, Dict[str, Any]]] = None, **kw: Any) -> Any:
            tok = self.pair() if not self.hub.paired() else self.tok
            self.tok = tok
            e = FakeExt(self, tok, **kw)
            if tabs is not None:
                e.tabs = tabs
            self.exts.append(e)
            e.start()
            end = time.time() + 5
            while time.time() < end and not self.hub.connected():                                                        # like the real worker: its first poll marks it connected
                time.sleep(0.02)
            return e

        class _Ext:
            pass

        # -- packaging / permissions -------------------------------------------------------------------------------------------------------------
        def test_embedded_assets_are_a_valid_minimal_mv3_extension(self) -> None:
            m = pc_manifest()
            self.assertEqual(m["manifest_version"], 3)
            self.assertEqual(set(m["permissions"]), {"debugger", "tabs", "storage", "alarms"})
            self.assertEqual(m["host_permissions"], ["http://127.0.0.1/*"])
            self.assertNotIn("<all_urls>", json.dumps(m))
            self.assertEqual(m["name"], "AI Web Bridge")
            self.assertEqual(m["icons"]["48"], "icons/icon48.png")
            self.assertIn("tabs you approve", m["description"])
            assets = pc_assets()
            for rel in (m["background"]["service_worker"], m["action"]["default_popup"], m["options_ui"]["page"]):
                self.assertIn(rel, assets)
            for size in (16, 32, 48, 128):
                icon = assets[f"icons/icon{size}.png"]
                self.assertTrue(icon.startswith(b"\x89PNG\r\n\x1a\n"))
                self.assertEqual(struct.unpack(">II", icon[16:24]), (size, size))
                pos, image_data, ended = 8, bytearray(), False
                while pos < len(icon):
                    length = struct.unpack(">I", icon[pos:pos + 4])[0]
                    kind, payload = icon[pos + 4:pos + 8], icon[pos + 8:pos + 8 + length]
                    crc = struct.unpack(">I", icon[pos + 8 + length:pos + 12 + length])[0]
                    self.assertEqual(crc, zlib.crc32(kind + payload) & 0xffffffff)
                    if kind == b"IDAT": image_data.extend(payload)
                    pos += 12 + length
                    if kind == b"IEND": ended = True; break
                self.assertTrue(ended)
                self.assertEqual(len(zlib.decompress(image_data)), size * (1 + size * 4))
            for rel in ("popup.html", "options.html"):
                for ref in re.findall(r'(?:src|href)="([^"]+)"', assets[rel]):
                    self.assertIn(ref, assets)
            for name, text in assets.items():                                                                             # no embedded secret: no long random-looking literal anywhere
                if isinstance(text, bytes):
                    continue
                self.assertEqual(re.findall(r"['\"][A-Za-z0-9_\-]{32,}['\"]", text), [], name)

        def test_extraction_is_repeatable_verified_and_confined(self) -> None:
            root = self.tmp / "pcx"
            (root / "extension").mkdir(parents=True)
            (root / "extension" / "unrelated.txt").write_text("keep me")
            r1 = pc_extract(root)
            self.assertEqual(sorted(r1["changed"]), sorted(pc_assets()))
            self.assertEqual(pc_extract(root)["changed"], [])
            (root / "extension" / "background.js").write_text("tampered")
            self.assertEqual(pc_extract(root)["changed"], ["background.js"])
            self.assertEqual((root / "extension" / "unrelated.txt").read_text(), "keep me")
            on_disk = json.loads((root / "extension.sha256.json").read_text())["files"]
            for rel, h in on_disk.items():
                self.assertEqual(hashlib.sha256((root / "extension" / rel).read_bytes()).hexdigest(), h)

        def test_extension_scripts_parse(self) -> None:
            import shutil as sh
