        def test_disconnect_midflight_unsafe_is_never_repeated_safe_is_resumed(self) -> None:
            e = self.fake(hold={"tab.create", "tabs.list"})
            out: Dict[str, Any] = {}

            def unsafe() -> None:
                try:
                    self.hub.call("tab.create", {"url": "about:blank"}, timeout=15)
                except PCError as x:
                    out["unsafe"] = x

            def safe() -> None:
                try:
                    out["safe"] = self.hub.call("tabs.list", {}, timeout=15)
                except PCError as x:
                    out["safe_err"] = x
            ts = [threading.Thread(target=unsafe), threading.Thread(target=safe)]
            for t in ts:
                t.start()
            time.sleep(0.8)
            e.stop()                                                                                                     # the extension goes away holding both commands
            ts[0].join(8)
            self.assertTrue(out["unsafe"].unknown_outcome)
            e2 = self.fake()                                                                                             # and comes back
            ts[1].join(10)
            self.assertIn("safe", out, out)
            self.assertEqual(sum(1 for x in e2.executed if x[0] == "tab.create"), 0)                                     # the unsafe one was NOT sent again
            self.assertGreaterEqual(self.hub.epoch, 2)

