        def test_a_verification_brings_the_tab_to_the_front_waits_for_the_owner_and_then_continues(self) -> None:
            from unittest import mock

            class Pg:
                url = "https://site.test/"

                def __init__(self) -> None:
                    self.front, self.waits = 0, 0

                def bring_to_front(self) -> None:
                    self.front += 1

                def wait_for_timeout(self, ms: int) -> None:
                    self.waits += 1
            pg, states, said = Pg(), [{"blocked_by": "widget", "challenge": True}] * 4 + [{"blocked_by": "", "challenge": False}] * 3, []
            seq = iter(states)
            with mock.patch.dict(globals(), {"ui_page_state": lambda page: next(seq)}):
                ui_wait_ready(pg, timeout=5, say=said.append, poll_ms=1)                                                 # 5 s would be too short for a human: the wait is stretched
            self.assertEqual(pg.front, 1)                                                                                # shown once, not on every poll
            self.assertTrue(any("verification" in m for m in said))
            seq2 = iter([{"blocked_by": "no_input", "challenge": False}] * 40)
            pg2 = Pg()
            with mock.patch.dict(globals(), {"ui_page_state": lambda page: next(seq2)}):
                with self.assertRaises(BridgeError):
                    ui_wait_ready(pg2, timeout=1, poll_ms=1)
            self.assertEqual(pg2.front, 0)                                                                               # no challenge: the owner's tab is not pulled to the front

        def test_locator_click_fill_keys_use_trusted_input_events(self) -> None:
            e = self.fake()
            ctx = self.ctx(e)
            pg = ctx.new_page()
            seen: List[Any] = []

            def ev(code: str) -> Any:
                m = re.search(r"\[(\{.*\}), \"(\w+)\", (.*)\]\)$", code, re.S)
                op = m.group(2) if m else ""
                seen.append(op)
                if op == "rect":
                    return {"found": True, "x": 50.0, "y": 60.0, "vis": True, "enabled": True, "hit": True}
                if op == "focus":
                    return {"found": True, "kind": "field", "editable": True}
                if op == "value":
                    return {"found": True, "v": "hello"}
                if op == "count":
                    return {"found": True, "v": 2}
                return {"found": False}
            e.eval_fn = ev
            self.assertEqual(pg.locator("textarea:visible").count(), 2)
            pg.locator("button").first.click(timeout=2000)
            kinds = [x[1].get("type") for x in e.input_log if x[0] == "Input.dispatchMouseEvent"]
            self.assertEqual(kinds, ["mouseMoved", "mousePressed", "mouseReleased"])
            pg.locator("textarea").last.fill("hello", timeout=2000)
            self.assertIn(("Input.insertText", {"text": "hello"}), e.input_log)
            pg.keyboard.press("Enter")
            self.assertTrue(any(x[0] == "Input.dispatchKeyEvent" and x[1].get("key") == "Enter" for x in e.input_log))
            with self.assertRaises(PCError) as cm:                                                                       # honest timeout instead of a fake success
                e.eval_fn = lambda code: {"found": False}
                pg.locator("#nope").click(timeout=300)
            self.assertIn("Timeout", str(cm.exception))
            ctx.close()

        def test_network_events_reach_capture_and_cdp_recorder(self) -> None:
            e = self.fake()
            ctx = self.ctx(e)
            cap = Capture(ctx)
            rec = CdpRecorder(ctx)
            pg = ctx.new_page()
            rec.start()
            self.assertEqual(rec.errors, [])
            m0 = cap.mark()
            e.bodies["R1"] = ('{"ok":true}', False)
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R1", "type": "Fetch", "frameId": "F", "timestamp": 1.0, "wallTime": time.time(),
                                                           "request": {"url": "https://site.test/api/chat", "method": "POST", "headers": {"Content-Type": "application/json"}, "postData": '{"q":1}', "hasPostData": True},
                                                           "initiator": {"type": "script"}})
            e.emit(pg.tab_id, "Network.requestWillBeSentExtraInfo", {"requestId": "R1", "headers": {"Content-Type": "application/json", "Cookie": "s=1"}})
            e.emit(pg.tab_id, "Network.responseReceived", {"requestId": "R1", "timestamp": 1.1, "response": {"url": "https://site.test/api/chat", "status": 200, "headers": {"Content-Type": "application/json"}, "mimeType": "application/json"}})
            e.emit(pg.tab_id, "Network.loadingFinished", {"requestId": "R1", "timestamp": 1.2})
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R2", "type": "Script", "request": {"url": "https://site.test/app.js", "method": "GET", "headers": {}}, "timestamp": 1.3})
            e.emit(pg.tab_id, "Network.responseReceived", {"requestId": "R2", "response": {"url": "https://site.test/app.js", "status": 200, "headers": {}}})
            e.bodies["R2"] = ("console.log(1)", False)
            e.emit(pg.tab_id, "Network.loadingFinished", {"requestId": "R2", "timestamp": 1.4})
            e.emit(pg.tab_id, "Network.requestWillBeSent", {"requestId": "R3", "type": "XHR", "request": {"url": "https://site.test/never", "method": "GET", "headers": {}}, "timestamp": 1.5})
            e.emit(pg.tab_id, "Network.loadingFailed", {"requestId": "R3", "errorText": "net::ERR_CONNECTION_RESET"})
            e.flush()
            self.assertTrue(ctx.drain(5))
            snap = cap.snapshot(m0, settle=2.0)
            self.assertEqual([s["url"] for s in snap], ["https://site.test/api/chat", "https://site.test/never"])
            self.assertEqual((snap[0]["status"], snap[0]["body"], snap[0]["resp_body"]), (200, '{"q":1}', '{"ok":true}'))
            self.assertEqual(snap[0]["headers"].get("cookie"), "s=1")                                                    # the raw (extra-info) headers win, as with Playwright's all_headers()
            self.assertEqual(snap[1]["status"], 0)                                                                       # a failed request is reported as failed, not as success
            self.assertEqual([u for u, _b in cap.script_bodies()], ["https://site.test/app.js"])
            raws = rec.raw_exchanges()
            self.assertTrue(any(x.get("url") == "https://site.test/api/chat" for x in raws))
            ctx.close()

