            tmp, store, cfg, app = mk_env()
            s = socket.socket()
            s.bind(("127.0.0.1", 0))
            port = s.getsockname()[1]
            s.close()
            srv = serve(app, port)
            old_hub = globals().get("PC_HUB")
            globals()["PC_HUB"] = self.hub
            try:
                H = {"x-admin-key": cfg["admin_key"]}
                self.assertEqual(call(port, "GET", "/api/personal-chrome")[0], 401)                                      # admin only
                st, _h, b = call(port, "GET", "/api/personal-chrome", headers=H)
                j = json.loads(b)
                self.assertEqual((st, j["status"]["paired"], j["status"]["connected"]), (200, False, False))
                self.assertTrue(j["capabilities"] and "chrome://extensions" in j["instructions"])
                self.fake()
                j = json.loads(call(port, "GET", "/api/personal-chrome", headers=H)[2])
                self.assertTrue(j["status"]["connected"])
                self.assertNotIn(self.tok, json.dumps(j))                                                                 # no secret ever leaves through the API
                st, _h, b = call(port, "POST", "/api/personal-chrome/pair", body={}, headers=H)
                self.assertEqual(st, 200)
                self.assertEqual(len(json.loads(b)["code"]), 8)
                from unittest import mock
                with mock.patch("webbrowser.open_new_tab", return_value=True) as open_page, mock.patch("os.startfile", create=True) as open_folder:
                    st, _h, b = call(port, "POST", "/api/personal-chrome/setup", body={}, headers=H)
                setup = json.loads(b)
                self.assertEqual(st, 200)
                self.assertEqual(len(setup["code"]), 8)
                self.assertFalse(setup["chrome_page_opened"])                                      # setup must not choose a Chrome profile for the owner
                self.assertTrue(setup["folder_opened"])
                self.assertTrue(Path(setup["extension_dir"], "manifest.json").is_file())
                open_page.assert_not_called()
                if os.name == "nt":                                                                       # os.startfile is the Windows way to open a folder
                    open_folder.assert_called_once_with(setup["extension_dir"])
                self.assertNotIn(setup["code"], json.dumps(pc_api_status()))
                self.assertIn("pc_start", DASHBOARD_HTML)
                self.assertIn("pc_security", DASHBOARD_HTML)
            finally:
                globals()["PC_HUB"] = old_hub
                srv.shutdown()
                shutil.rmtree(tmp, ignore_errors=True)

