        # ---- 7.88: manual mode, skip at once, pause / resume / cancel -------------------------------------------------------------------
        def test_manual_mode_marks_red_and_skips_but_starts_nothing_by_itself(self) -> None:
            self.cfg.data["guard_enabled"] = False
            self.fail("a1", "empty_response")
