        def test_a_stale_reply_from_the_previous_task_is_not_reformatted(self) -> None:
            sent: List[str] = []
            good1 = '{"a": "x"}'
            good2 = '{"b": "y"}'
            replies = [good1, good1, good2]                                                # the page still shows task 1's answer for task 2
            def send(prompt: str) -> str:
                sent.append(prompt)
                return replies[len(sent) - 1]
            br = Brain(send)
